// taking the class's equipment package, {dice: "NdM", mult}. See dnd.su class
// pages for each class's table.
export const CLASS_STARTING_GOLD = {
  barbarian: { dice: "2d4", mult: 10 },
  bard: { dice: "5d4", mult: 10 },
  cleric: { dice: "5d4", mult: 10 },
  druid: { dice: "2d4", mult: 10 },
  fighter: { dice: "5d4", mult: 10 },
  monk: { dice: "5d4", mult: 1 },
  paladin: { dice: "5d4", mult: 10 },
  ranger: { dice: "5d4", mult: 10 },
  rogue: { dice: "4d4", mult: 10 },
  sorcerer: { dice: "3d4", mult: 10 },
  warlock: { dice: "4d4", mult: 10 },
  wizard: { dice: "4d4", mult: 10 },
  artificer: { dice: "5d4", mult: 10 },
};

// Pulls a starting-gold amount out of a background's free-text `equipment`
// string (e.g. "...поясной кошель с 15 зм" -> {gp: 15}), for auto-filling
// money at character creation. Picks the LAST зм/платин mention, since the
// coin pouch is always listed last in these strings.
export function extractStartingGold(text) {
  const result = { pp: 0, gp: 0, sp: 0, cp: 0 };
  if (!text) return result;
  const gpMatches = [...text.matchAll(/(\d+)\s*зм(?![а-яёА-ЯЁ])/gi)];
  if (gpMatches.length) result.gp = parseInt(gpMatches[gpMatches.length - 1][1], 10) || 0;
  const ppMatches = [...text.matchAll(/(\d+)\s*платин[а-яёА-ЯЁ]*/gi)];
  if (ppMatches.length) result.pp = parseInt(ppMatches[ppMatches.length - 1][1], 10) || 0;
  return result;
}

// Removes the same starting-gold mention extractStartingGold() picks out
// (the LAST "N зм" in the text) from a background's equipment description,
// so the coin amount — which extractStartingGold() already moved into the
// character's Деньги section — doesn't also show up in the free-text
// "прочее снаряжение" list. Only the actual coin total is stripped; an item
// valuation elsewhere in the same text ("самоцвет стоимостью 10 зм") is left
// alone since it isn't preceded by "с"/"на сумму" right before the amount.
export function stripStartingGoldMention(text) {
  if (!text) return text;
  const re = /(\d+)\s*зм(?![а-яёА-ЯЁ])/gi;
  let lastMatch = null;
  let m;
  while ((m = re.exec(text))) lastMatch = m;
  if (!lastMatch) return text;
  const start = lastMatch.index;
  const end = start + lastMatch[0].length;
  let before = text.slice(0, start);
  let after = text.slice(end);
  // Swallow a wrapping "(...)" around the amount, e.g. "(10 зм)".
  if (/\(\s*$/.test(before) && /^\s*\)/.test(after)) {
    before = before.replace(/\(\s*$/, "");
    after = after.replace(/^\s*\)/, "");
  }
  // Swallow a preposition directly preceding the amount ("кошель с 15 зм"
  // -> "кошель"). \b doesn't fire next to Cyrillic letters in JS regex, so
  // the boundary is spelled out with (?:^|\s) / (?=\s*$) instead of \b.
  before = before.replace(/(?:^|\s)(?:с|на сумму)(?=\s*$)/i, "").replace(/\s+$/, "");
  let result = `${before} ${after}`.replace(/\s+/g, " ").trim();
  result = result.replace(/\s+;/g, ";").replace(/;\s*;/g, ";").replace(/^;\s*/, "").replace(/;\s*$/, "");
  return result;
}

// Class features in CLASSES[].features are single strings that pack the
// description into a trailing "(...)", e.g. "Ярость (бонус к урону,
// сопротивление физ. урону)" — fine for the wizard's compact step list, but
// when seeded into a character's "Умения" (data.features), that meant the
// whole parenthetical ended up jammed into the card's title with the
// description left blank. This splits it into a short name plus the actual
// description text, so features like "Второе дыхание"/"Ярость" show up on
// their card fully written out instead of empty.
export function splitFeatureText(text) {
  // Name up to the first " (", description = everything inside the outer
  // parentheses (may itself contain nested parentheses).
  const m = String(text || "").match(/^([^(]*?)\s*\((.*)\)\s*$/);
  if (m) return { name: m[1].trim(), desc: m[2].trim() };
  return { name: String(text || "").trim(), desc: "" };
}

// Shared copies of wizard.js's own subclass-feature-text choice parsers, so
// sheet.js's level-up modal can recognize the very same "владение одним из
// следующих навыков: ..." / "N навыком(-ами) на выбор" / "выучить N языков
// на свой выбор" wording at ANY level a subclass grants it (not just level
// 1, which is all wizard.js ever needed since character creation only ever
// deals with a level-1 subclass pick). Kept as separate exported copies
// rather than having wizard.js import these (and delete its own private
// versions) to avoid touching working, already-tested creation-time code
// while adding this.
export const SKILL_CHOICE_COUNT_WORDS = { "одним": 1, "одна": 1, "одно": 1, "двумя": 2, "тремя": 3, "четырьмя": 4, "пятью": 5 };
export function parseSkillChoiceGrant(desc) {
  const text = String(desc || "");
  const m = /владение\s+(одним|одна|одно|двумя)\s+(?:навык(?:ом|ами)\s+)?(?:по\s+вашему\s+выбору\s+)?из\s+(?:следующего\s+списка|следующих\s+навыков)(?:\s+по\s+вашему\s+выбору)?:\s*([^.]+)\./i.exec(text);
  if (!m) return null;
  const count = SKILL_CHOICE_COUNT_WORDS[m[1].toLowerCase()] || 1;
  const optionIds = m[2]
    .split(/\s*,\s*|\s+или\s+|\s+и\s+/i)
    .map((s) => s.trim())
    .filter(Boolean)
    .map((nm) => SKILLS.find((s) => s.label.toLowerCase() === nm.toLowerCase()))
    .filter(Boolean)
    .map((s) => s.id);
  if (!optionIds.length) return null;
  const expertise = /бонус мастерства удваивается/i.test(text);
  return { count, optionIds, expertise };
}
export function parseFreeSkillChoiceGrant(desc) {
  const text = String(desc || "");
  const m = /(?:владение|овладеваете)\s+(одним|одна|одно|двумя|тремя|четырьмя|пятью)\s+навык(?:ом|ами|а)\s+на\s+(?:ваш\s+)?выбор\.?\s*$/i.exec(text.trim());
  if (!m) return null;
  return { count: { ...SKILL_CHOICE_COUNT_WORDS, "тремя": 3, "четырьмя": 4, "пятью": 5 }[m[1].toLowerCase()] || 1 };
}
const LANGUAGE_CHOICE_COUNT_WORDS = { "один": 1, "одно": 1, "два": 2, "две": 2, "три": 3 };
export function parseLanguageChoiceGrant(desc) {
  // "выучить N языков на свой выбор" (most subclasses) vs Комбинатор
  // «Интриган»'s "вы также учите два языка по вашему выбору" -- same grant,
  // different verb ("учите" not "выучить") and possessive phrasing ("по
  // вашему выбору" not "на свой выбор").
  const m = /(?:выучить|учите|изучаете)\s+(\d+|один|одно|два|две|три)\s+язы[кав]+\s+(?:на свой выбор|по вашему выбору)/i.exec(String(desc || ""));
  if (!m) return 0;
  return /^\d+$/.test(m[1]) ? Number(m[1]) : LANGUAGE_CHOICE_COUNT_WORDS[m[1].toLowerCase()] || 0;
}

