// Detects an ARMORS id / whether a shield is mentioned from free-text
// equipment strings (e.g. a class's startEquipment choice text), so armor
// chosen during character creation can auto-equip and drive AC.
export function detectArmorIdFromText(text) {
  if (!text) return null;
  const t = text.toLowerCase();
  const rules = [
    ["проклёпанный", "studded-leather"],
    ["кольчужн", "chain-shirt"],
    ["чешуйчат", "scale-mail"],
    ["кольчуг", "chain-mail"],
    ["кожан", "leather"],
    ["шкурн", "hide"],
    ["кираса", "breastplate"],
    ["полулат", "half-plate"],
    ["колечн", "ring-mail"],
    ["наборн", "splint"],
    ["латы", "plate"],
    ["стёган", "padded"],
  ];
  for (const [kw, id] of rules) {
    if (t.includes(kw)) return id;
  }
  return null;
}
export function textMentionsShield(text) {
  return !!text && /щит/i.test(text);
}

// Loosely matches a catalog item's name (WEAPONS/ARMORS) against free-text
// equipment strings that use a different grammatical case ("два коротких
// мечей", "пять метательных копий", "10 дротиков"…). Russian declines nouns
// and adjectives by case/number, so a plain substring check on the nominative
// name misses most of these. Instead, every significant word of the name is
// reduced to a short stem (its first few letters, which case endings don't
// touch) and checked as a substring — good enough for this curated dataset.
export function equipmentNameMatches(lowerText, name) {
  const words = name.toLowerCase().split(/\s+/).filter((w) => w.length >= 3);
  if (!words.length) return false;
  // Words must appear adjacent and in order (each stem optionally followed by
  // more letters, i.e. its own case ending, then whitespace, then the next
  // stem) — not just anywhere in the text — so e.g. "короткий" from one item
  // and "лук" from an unrelated item elsewhere in the same string can't
  // combine into a false "короткий лук" match.
  const stems = words.map((w) => (w.length > 4 ? w.slice(0, w.length - 2) : w.slice(0, Math.max(3, w.length - 1))));
  const escaped = stems.map((s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"));
  // \w in JS regex doesn't match Cyrillic letters, so a bare Cyrillic-letter
  // class is used to consume the rest of each declined word instead.
  const rest = "[а-яёА-ЯЁ]*";
  const pattern = new RegExp(escaped.join(rest + "\\s+") + rest, "i");
  return pattern.test(lowerText);
}

// Detects WEAPONS entries mentioned by name in free-text equipment strings
// (e.g. a class's chosen starting-equipment option), so they can be added to
// the character's structured weapon list automatically at creation. Longer
// names are matched first so "короткий меч" wins over a bare "меч".
export function detectWeaponsInText(text) {
  if (!text) return [];
  const lower = text.toLowerCase();
  const found = [];
  [...WEAPONS]
    .filter((w) => w.id !== "unarmed" && w.id !== "custom")
    .sort((a, b) => b.name.length - a.name.length)
    .forEach((w) => {
      if (equipmentNameMatches(lower, w.name) && !found.some((f) => f.id === w.id)) {
        found.push(w);
      }
    });
  return found;
}

const RU_NUMBER_WORDS = {
  один: 1, одна: 1, два: 2, две: 2, три: 3, четыре: 4, пять: 5,
  шесть: 6, семь: 7, восемь: 8, девять: 9, десять: 10, двадцать: 20, тридцать: 30,
};

// Pulls starting ammo counts out of a free-text equipment string (e.g. a
// class's chosen starting equipment: "длинный лук и колчан из 20 стрел",
// "лёгкий арбалет и 20 болтов", "10 дротиков", "пять метательных копий"),
// so the character's ammo tracker starts pre-filled instead of at 0.
export function detectAmmoInText(text) {
  const result = {};
  if (!text) return result;
  const lower = text.toLowerCase();
  const numberPattern = `(\\d+|${Object.keys(RU_NUMBER_WORDS).join("|")})`;
  const rules = [
    ["arrows", "стрел"],
    ["bolts", "болт"],
    ["darts", "дротик"],
    // "копья"/"копьё" (2-4 of something) keeps the ь, but "копий" (5+,
    // genitive plural -- "пять метательных копий") drops it for an и --
    // matching just "копь" silently missed that declension.
    ["javelins", "коп[ьи]"],
  ];
  rules.forEach(([key, kw]) => {
    const re = new RegExp(`${numberPattern}[^,;.]{0,20}?${kw}`, "i");
    const m = lower.match(re);
    if (m) {
      const n = /^\d+$/.test(m[1]) ? parseInt(m[1], 10) : RU_NUMBER_WORDS[m[1]] || 0;
      if (n) result[key] = n;
    }
  });
  return result;
}

// Named-weapon lists for traits that grant proficiency in a short, specific
// list of weapons rather than a whole category ("простое"/"воинское" оружие)
// -- Russian noun declension in the trait's own prose (e.g. "боевым топором")
// makes reliably re-deriving the exact list from free text too fragile, so
// these are captured explicitly by trait name instead. Keyed by the trait
// NAME exactly as it appears in RACES/CLASSES (matches splitFeatureText()'s
// parsed name), values are WEAPONS names (see WEAPONS above) in nominative.
export const TRAIT_NAMED_WEAPON_GRANTS = {
  "Дварфская боевая тренировка": ["Боевой топор", "Ручной топор", "Лёгкий молот", "Боевой молот"],
  "Владение оружием эльфов": ["Длинный меч", "Короткий меч", "Длинный лук", "Короткий лук"],
};

// Detects a feature/trait granting armor or weapon PROFICIENCY (as opposed to
// detectWeaponsInText/detectArmorIdFromText above, which detect specific
// items in starting-equipment text) from its free-text description, so the
// grant can be folded automatically into data.proficiencies.armor/.weapons
// instead of sitting inert inside a flavor-text feature card.
//
// Only sentences that actually contain proficiency-granting language ("влад-")
// are scanned -- a long paragraph can mention "доспехом" or "щитом" in an
// unrelated sense (e.g. Rune Knight's "Резчик рун" naming them only as
// example item types a rune can be etched onto), so gating on "влад-"
// co-occurring in the SAME SENTENCE avoids false positives from those.
// Named tool kits mentioned in "владение <kit>" prose (Плут «Убийца»'s
// "Дополнительные владения": "набор для грима и инструментами отравителя",
// «Комбинатор»'s "Интриган": "набор для грима, набор для фальсификации..."),
// matched against the same TOOL_GROUPS catalog names the rest of the app
// already uses for proficiency lists. Each entry's own wording (e.g. набор
// vs инструменты) varies across sourcebooks, so this matches on whichever
// distinctive noun the kit is actually named for rather than the exact
// catalog string.
const NAMED_TOOL_TEXT_PATTERNS = [
  { re: /набор[а-я]*\s+для\s+грима/i, name: "Набор для грима" },
  { re: /набор[а-я]*\s+для\s+фальсификации/i, name: "Набор для фальсификации" },
  { re: /(набор|инструмент)[а-я]*\s+травника/i, name: "Набор травника" },
  { re: /(набор|инструмент)[а-я]*\s+пивовара/i, name: "Инструменты пивовара" },
  { re: /инструмент[а-я]*\s+навигатора/i, name: "Инструменты навигатора" },
  { re: /(набор[а-я]*|инструмент[а-я]*)\s+отравителя/i, name: "Набор отравителя" },
  { re: /воровск[а-я]*\s+инструмент[а-я]*/i, name: "Воровские инструменты" },
  { re: /инструмент[а-я]*\s+кузнеца/i, name: "Инструменты кузнеца" },
];
export function parseProficiencyGrantsFromText(desc) {
  const result = { armor: [], weapons: [], tools: [] };
  if (!desc) return result;
  const sentences = String(desc)
    .replace(/ё/gi, (c) => (c === "Ё" ? "Е" : "е"))
    .split(/(?<=[.!?])\s+/);
  sentences.forEach((sentRaw) => {
    const sent = sentRaw.toLowerCase();
    if (!/влад[а-я]*/i.test(sent)) return;
    // Armor categories -- an adjective (легк-/средн-/тяжел-) co-occurring
    // with a доспех-/брон- noun in the same clause.
    if (/легк[а-я]*[^.!?]{0,15}(доспех|брон)[а-я]*/i.test(sent) || /(доспех|брон)[а-я]*[^.!?]{0,15}легк[а-я]*/i.test(sent)) {
      if (!result.armor.includes("Лёгкая броня")) result.armor.push("Лёгкая броня");
    }
    if (/средн[а-я]*[^.!?]{0,15}(доспех|брон)[а-я]*/i.test(sent) || /(доспех|брон)[а-я]*[^.!?]{0,15}средн[а-я]*/i.test(sent)) {
      if (!result.armor.includes("Средняя броня")) result.armor.push("Средняя броня");
    }
    if (/тяжел[а-я]*[^.!?]{0,15}(доспех|брон)[а-я]*/i.test(sent) || /(доспех|брон)[а-я]*[^.!?]{0,15}тяжел[а-я]*/i.test(sent)) {
      if (!result.armor.includes("Тяжёлая броня")) result.armor.push("Тяжёлая броня");
    }
    if (/щит[а-я]*/i.test(sent)) {
      if (!result.armor.includes("Щиты")) result.armor.push("Щиты");
    }
    NAMED_TOOL_TEXT_PATTERNS.forEach(({ re, name }) => {
      if (re.test(sent) && !result.tools.includes(name)) result.tools.push(name);
    });
    // Weapon categories.
    if (/воинск[а-я]*[^.!?]{0,10}оруж[а-я]*/i.test(sent)) {
      if (!result.weapons.includes("Воинское оружие")) result.weapons.push("Воинское оружие");
    } else if (/прост[а-я]*[^.!?]{0,10}оруж[а-я]*/i.test(sent)) {
      if (!result.weapons.includes("Простое оружие")) result.weapons.push("Простое оружие");
    }
    // Named individual weapons (rather than a whole category) are NOT
    // detected here -- detectWeaponsInText's short stem-matching is meant for
    // compact equipment-list strings and is too prone to false hits inside a
    // long prose sentence (e.g. its "Сеть"/"net" stem "сет" matching inside
    // the unrelated word "несёте" -- "[you] carry/wear"). Named-weapon grants
    // use the explicit TRAIT_NAMED_WEAPON_GRANTS lookup above instead.
  });
  return result;
}

// Expands any EQUIPMENT_PACK_DESCRIPTIONS pack name found in a free-text
// equipment string into "Название (полное содержимое)", so a chosen pack's
// contents show up directly in the equipment list rather than only on hover.
// Longest keys first so "набор исследователя подземелий" isn't swallowed by a shorter alias.
export function expandPackContents(text) {
  if (!text) return text;
  let result = text;
  Object.entries(EQUIPMENT_PACK_DESCRIPTIONS)
    .sort((a, b) => b[0].length - a[0].length)
    .forEach(([key, desc]) => {
      const re = new RegExp(key.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"), "i");
      if (re.test(result) && !result.includes(`(${desc}`)) {
        result = result.replace(re, (m) => `${m} (${desc})`);
      }
    });
  return result;
}

