(function applyRound58Data() {
  const spellName = (id) => (SPELLS.find((s) => s.id === id) || {}).name || id;
  // --- Варвар: полный текст Всплеска дикости + таблица
  const barb = CLASSES.find((c) => c.id === "barbarian");
  const wild = barb && barb.subclasses.find((s) => s.slug === "wild-magic");
  const surge = wild && wild.features.find((f) => f.name === "Всплеск дикости");
  if (surge && !surge.desc.some((d) => /^1\. /.test(d))) {
    surge.desc = surge.desc.filter((d) => d !== "Дикая магия");
    surge.desc.push("Таблица «Дикая магия» (к8):");
    WILD_MAGIC_SURGE_TABLE.forEach((r) => surge.desc.push(`${r.roll}. ${r.text}`));
  }
  // --- Паладин: заклинания клятв
  const pal = CLASSES.find((c) => c.id === "paladin");
  if (!pal) return;
  const OATH_SPELLS = {
    "Клятва преданности": [["protection-from-evil-and-good", "sanctuary"], ["lesser-restoration", "zone-of-truth"], ["beacon-of-hope", "dispel-magic"], ["freedom-of-movement", "guardian-of-faith"], ["commune", "flame-strike"]],
    "Клятва древних": [["ensnaring-strike", "speak-with-animals"], ["moonbeam", "misty-step"], ["plant-growth", "protection-from-energy"], ["ice-storm", "stoneskin"], ["commune-with-nature", "tree-stride"]],
    "Клятва мести": [["bane", "hunters-mark"], ["hold-person", "misty-step"], ["haste", "protection-from-energy"], ["banishment", "dimension-door"], ["hold-monster", "scrying"]],
    "Клятвопреступник": [["hellish-rebuke", "inflict-wounds"], ["crown-of-madness", "darkness"], ["animate-dead", "bestow-curse"], ["blight", "confusion"], ["contagion", "dominate-person"]],
    "Клятва короны": [["command", "compelled-duel"], ["warding-bond", "zone-of-truth"], ["aura-of-vitality", "spirit-guardians"], ["banishment", "guardian-of-faith"], ["circle-of-power", "geas"]],
    "Клятва искупления": [["sanctuary", "sleep"], ["calm-emotions", "hold-person"], ["counterspell", "hypnotic-pattern"], ["otilukes-resilient-sphere", "stoneskin"], ["hold-monster", "wall-of-force"]],
    "Клятва покорения": [["armor-of-agathys", "command"], ["hold-person", "spiritual-weapon"], ["bestow-curse", "fear"], ["dominate-beast", "stoneskin"], ["cloudkill", "dominate-person"]],
    "Клятва славы": [["guiding-bolt", "heroism"], ["enhance-ability", "magic-weapon"], ["haste", "protection-from-energy"], ["compulsion", "freedom-of-movement"], ["commune", "flame-strike"]],
    "Клятва смотрителей": [["alarm", "detect-magic"], ["moonbeam", "see-invisibility"], ["counterspell", "nondetection"], ["aura-of-purity", "banishment"], ["hold-monster", "scrying"]],
  };
  const TIER_LEVELS = [3, 5, 9, 13, 17];
  pal.subclasses.forEach((sub) => {
    const tiers = OATH_SPELLS[sub.name];
    if (!tiers) return;
    sub.domainSpells = tiers.map((spells, i) => ({ level: TIER_LEVELS[i], spells }));
    const lines = ["Вы получаете заклинания клятвы на указанных уровнях паладина. Они всегда подготовлены и не считаются в лимит подготовленных заклинаний."];
    sub.domainSpells.forEach((t) => lines.push(`${t.level}-й уровень паладина: ${t.spells.map(spellName).join(", ")}`));
    let f = sub.features.find((x) => x.name === "Заклинания клятвы");
    if (f) f.desc = lines;
    else sub.features.unshift({ name: "Заклинания клятвы", level: 3, desc: lines });
  });
  // --- Паладин: полные тексты умений, у которых остался только короткий пересказ
  Object.assign(pal.classFeatureText, {
    "Аура защиты": "Начиная с 6-го уровня, когда вы или дружественное существо в пределах 10 футов от вас должны совершить спасбросок, это существо получает бонус к спасброску, равный вашему модификатору Харизмы (минимальный бонус +1). Вы должны находиться в сознании, чтобы даровать этот бонус. На 18-м уровне радиус этой ауры увеличивается до 30 футов.",
    "Аура отваги": "Начиная с 10-го уровня, вы и дружественные существа в пределах 10 футов от вас не можете быть испуганы, пока вы находитесь в сознании. На 18-м уровне радиус этой ауры увеличивается до 30 футов.",
    "Аура защиты и Аура отваги": "Радиус «Ауры защиты» и «Ауры отваги» увеличивается до 30 футов.",
    "Улучшенная божественная кара": "Начиная с 11-го уровня, вы настолько наполнены праведной силой, что все ваши рукопашные атаки оружием несут в себе божественную мощь. Когда вы попадаете по существу рукопашной атакой оружием, это существо получает дополнительный урон излучением 1к8. (В окне урона оружия этот кубик предлагается автоматически.)",
  });
})();

