export const FEAT_SOURCE_ORDER = ["Книга игрока", "Xanathar's Guide to Everything", "Sword Coast Adventurer's Guide", "Tasha's Cauldron of Everything", "Eberron: Rising from the Last War", "Fizban's Treasury of Dragons", "Planescape: Adventures in the Multiverse", "Bigby Presents: Glory of the Giants", "The Book of Many Things", "Dragonlance: Shadow of the Dragon Queen", "Strixhaven: A Curriculum of Chaos"];
export const METAMAGIC_OPTIONS = [{"name": "Аккуратное заклинание", "desc": "Когда вы накладываете заклинание, которое вынуждает других существ совершить спасбросок, вы можете защитить некоторых из них от магического воздействия. Вы тратите 1 единицу чародейства и выбираете существ в количестве, равном вашему модификатору Харизмы (минимум одно). Указанные существа автоматически преуспевают в спасброске от данного заклинания."}, {"name": "Далёкое заклинание", "desc": "При накладывании заклинания, дистанция которого 5 футов и более, вы можете потратить 1 единицу чародейства, чтобы удвоить это расстояние. При накладывании заклинания с дистанцией «касание», вы можете потратить 1 единицу чародейства, чтобы увеличить это расстояние до 30 футов."}, {"name": "Непреодолимое заклинание", "desc": "Когда вы накладываете заклинание, которое вынуждает существо совершить спасбросок для защиты от его эффектов, вы можете потратить 3 единицы чародейства, чтобы одна из целей заклинания совершила первый спасбросок от этого заклинания с помехой."}, {"name": "Неуловимое заклинание", "desc": "Во время накладывания заклинания вы можете потратить 1 единицу чародейства, чтобы наложить его без вербальных и соматических компонентов."}, {"name": "Продлённое заклинание", "desc": "При накладывании заклинания с длительностью 1 минута или более, вы можете потратить 1 единицу чародейства, чтобы удвоить это время, вплоть до максимального в 24 часа."}, {"name": "Удвоенное заклинание", "desc": "Если вы используете заклинание, нацеливаемое только на одно существо и не имеющее дистанцию «на себя», вы можете потратить количество единиц чародейства, равное уровню заклинания (1 для заговоров), чтобы нацелиться им на второе существо-цель в пределах дистанции этого заклинания. Заклинание не должно быть способно нацеливаться более чем на одну цель на текущем накладываемом уровне."}, {"name": "Усиленное заклинание", "desc": "При совершении броска урона от заклинания вы можете потратить 1 единицу чародейства, чтобы перебросить несколько костей урона в количестве не больше вашего модификатора Харизмы (минимум одна). Вы должны использовать новое выпавшее значение. Вы можете воспользоваться этим вариантом, даже если уже использовали другой вариант метамагии для этого заклинания."}, {"name": "Ускоренное заклинание", "desc": "Если вы накладываете заклинание со временем накладывания «1 действие», вы можете потратить 2 единицы чародейства, чтобы наложить это заклинание бонусным действием."}, {"name": "Ищущее заклинание", "desc": "Если вы совершаете бросок атаки для заклинания и промахиваетесь, вы можете потратить 2 единицы чародейства, чтобы перебросить к20, и должны использовать новый бросок. Вы можете использовать это умение, даже если уже использовали другой вариант метамагии при накладывании заклинания."}, {"name": "Преобразованное заклинание", "desc": "Когда вы накладываете заклинание, которое наносит тип урона из перечисленного списка, вы можете потратить 1 единицу чародейства и изменить этот тип урона на другой из следующих: звук, кислота, огонь, холод, электричество, яд."}];
export const ELDRITCH_INVOCATIONS = [{"name": "Ведьмачий взор", "req": "15-й уровень колдуна", "desc": "Вы можете видеть истинный облик всех перевёртышей и существ, скрытых магией школы Иллюзия или Преобразование, и находящихся в вашей линии обзора, и при этом в пределах 30 футов от вас."}, {"name": "Взор двух умов", "req": "", "desc": "Вы можете действием коснуться согласного Гуманоида и до конца своего следующего хода воспринимать всё его чувствами. Пока существо находится на том же плане существования, что и вы, вы можете в последующие ходы действием продлевать эту связь до конца своего следующего хода. При восприятии чувствами другого существа, вы получаете все преимущества от особых чувств, которыми обладает это существо, а сами при этом слепы и глухи для своего окружения."}, {"name": "Видения далёких королевств", "req": "15-й уровень колдуна", "desc": "Вы можете неограниченно накладывать заклинание магический глаз [arcane eye], не тратя ячейки заклинаний."}, {"name": "Вор пяти судеб", "req": "", "desc": "Вы можете один раз наложить заклинание порча [bane], используя ячейку заклинаний колдуна. Вы не можете сделать это повторно, пока не окончите продолжительный отдых."}, {"name": "Восходящий шаг", "req": "9-й уровень колдуна", "desc": "Вы можете неограниченно накладывать на себя заклинание левитация [levitate], не тратя ячейки заклинаний и материальные компоненты."}, {"name": "Глаза хранителя рун", "req": "", "desc": "Вы можете читать любые письмена."}, {"name": "Глас цепного мастера", "req": "умение «Договор цепи»", "desc": "Вы можете телепатически общаться со своим фамильяром и воспринимать всё чувствами фамильяра, пока вы находитесь на одном и том же плане существования. Кроме того, когда вы воспринимаете чувствами фамильяра, вы можете говорить через него своим собственным голосом, даже если фамильяр не способен говорить."}, {"name": "Доспех теней", "req": "", "desc": "Вы можете неограниченно накладывать на себя заклинание доспехи мага [mage armor], не тратя ячейки заклинаний и материальные компоненты."}, {"name": "Дьявольский взгляд", "req": "", "desc": "Вы можете нормально видеть в темноте, как магической, так и немагической, на расстоянии 120 футов."}, {"name": "Жаждущий клинок", "req": "5-й уровень колдуна, умение «Договор клинка»", "desc": "Вы можете атаковать своим оружием договора два раза вместо одного, когда в свой ход используете действие Атака."}, {"name": "Животная речь", "req": "", "desc": "Вы можете неограниченно накладывать заклинание разговор с животными [speak with animals], не тратя ячейки заклинаний."}, {"name": "Завораживающий шёпот", "req": "7-й уровень колдуна", "desc": "Вы можете один раз наложить заклинание принуждение [compulsion], используя ячейку заклинаний колдуна. Вы не можете сделать это повторно, пока не окончите продолжительный отдых."}, {"name": "Знак дурного предзнаменования", "req": "5-й уровень колдуна", "desc": "Вы можете один раз наложить заклинание проклятие [bestow curse], используя ячейку заклинаний колдуна. Вы не можете сделать это повторно, пока не окончите продолжительный отдых."}, {"name": "Книга древних секретов", "req": "умение «Договор гримуара»", "desc": "Теперь вы можете вписывать магические ритуалы в свою Книгу Теней. Выберите два заклинания 1-го уровня с ключевым словом «ритуал» из списков заклинаний любых классов. Эти заклинания появляются в книге и не учитываются в общем количестве заклинаний, которые вы можете знать. Держа Книгу Теней в руке, вы можете сотворять выбранные заклинания как ритуалы. Вы не можете накладывать заклинания иначе как ритуалом, если вы не узнали их иным способом. Вы также можете сотворять известные заклинания колдуна как ритуалы, если у них есть ключевое слово «ритуал». Во время приключений вы можете добавлять другие ритуальные заклинания в свою Книгу Теней. Когда вы найдёте такое заклинание, вы можете добавить его в книгу, если уровень заклинания не превышает половину вашего уровня колдуна (округляя в большую сторону) и если вы можете потратить время на переписывание заклинания. За каждый уровень заклинания время переписывания занимает 2 часа и стоит 50 золотых монет, которые должны быть потрачены на редкие чернила, необходимые для записи."}, {"name": "Маска многих лиц", "req": "", "desc": "Вы можете неограниченно накладывать заклинание маскировка [disguise self], не тратя ячейки заклинаний."}, {"name": "Мастер бесчисленных обликов", "req": "15-й уровень колдуна", "desc": "Вы можете неограниченно накладывать заклинание смена обличья [alter self], не тратя ячейки заклинаний."}, {"name": "Мистическое копьё", "req": "заговор мистический заряд [eldritch blast]", "desc": "Когда вы накладываете мистический заряд [eldritch blast], его дистанция равна 300 футам."}, {"name": "Могильный шёпот", "req": "9-й уровень колдуна", "desc": "Вы можете неограниченно накладывать заклинание разговор с мёртвыми [speak with dead], не тратя ячейки заклинаний."}, {"name": "Мощь исчадия", "req": "", "desc": "Вы можете неограниченно накладывать на себя заклинание псевдожизнь [false life] как заклинание 1-го уровня, не тратя ячейки заклинаний и материальные компоненты."}, {"name": "Мучительный взрыв", "req": "заговор мистический заряд [eldritch blast]", "desc": "Когда вы накладываете мистический заряд [eldritch blast], добавьте модификатор Харизмы к урону, причиняемому при попадании."}, {"name": "Обманчивое влияние", "req": "", "desc": "Вы получаете владение навыками Обман и Убеждение."}, {"name": "Один среди теней", "req": "5-й уровень колдуна", "desc": "Когда вы находитесь в области тусклого света или в темноте, вы можете действием стать невидимым, пока вы не переместитесь или не используете действие или реакцию."}, {"name": "Отталкивающий заряд", "req": "заговор мистический заряд [eldritch blast]", "desc": "Если вы попадаете по существу мистическим зарядом [eldritch blast], вы можете толкнуть его на 10 футов прочь от себя по прямой линии."}, {"name": "Потусторонний прыжок", "req": "9-й уровень колдуна", "desc": "Вы можете неограниченно накладывать на себя заклинание прыжок [jump], не тратя ячейки заклинаний и материальные компоненты."}, {"name": "Пьющий жизнь", "req": "12-й уровень колдуна, умение «Договор клинка»", "desc": "Когда вы попадаете по существу оружием договора, это существо получает дополнительный урон некротической энергией, равный вашему модификатору Харизмы (минимум 1)."}, {"name": "Скульптор плоти", "req": "7-й уровень колдуна", "desc": "Вы можете один раз наложить заклинание превращение [polymorph], используя ячейку заклинаний колдуна. Вы не можете сделать это повторно, пока не окончите продолжительный отдых."}, {"name": "Слуги хаоса", "req": "9-й уровень колдуна", "desc": "Вы можете один раз наложить заклинание призыв элементаля [conjure elemental], используя ячейку заклинаний колдуна. Вы не можете сделать это повторно, пока не окончите продолжительный отдых."}, {"name": "Таинственный взгляд", "req": "", "desc": "Вы можете неограниченно накладывать заклинание обнаружение магии [detect magic], не тратя ячейки заклинаний."}, {"name": "Трясина разума", "req": "5-й уровень колдуна", "desc": "Вы можете один раз наложить заклинание замедление [slow], используя ячейку заклинаний колдуна. Вы не можете сделать это повторно, пока не окончите продолжительный отдых."}, {"name": "Туманные видения", "req": "", "desc": "Вы можете неограниченно накладывать заклинание безмолвный образ [silent image], не тратя ячейки заклинаний и материальные компоненты."}, {"name": "Ужасающее слово", "req": "7-й уровень колдуна", "desc": "Вы можете один раз наложить заклинание смятение [confusion], используя ячейку заклинаний колдуна. Вы не можете сделать это повторно, пока не закончите продолжительный отдых."}, {"name": "Цепи карцери", "req": "15-й уровень колдуна, умение «Договор цепи»", "desc": "Вы можете неограниченно накладывать заклинание удержание чудовища [hold monster], если цель — Исчадие, Небожитель или Элементаль. При этом вы не тратите ячейки заклинаний и материальные компоненты. Вы должны закончить продолжительный отдых, прежде чем снова сможете использовать это заклинание против этого же существа."}];
(function applyRound60Feats() {
  FEATS.forEach((f) => { if (!f.source) f.source = "Книга игрока"; });
  const NEW_FEATS = [{"id": "rune-shaper", "name": "Ваятель рун", "nameEn": "Rune shaper", "source": "Bigby Presents: Glory of the Giants", "prereq": "умение «Использование заклинаний» или предыстория «Резчик рун»", "desc": "Вы изучили магию рун Великанов, что дает вам следующие преимущества:\nПонимание языков. Вы изучаете заклинание понимание языков [comprehend languages]. Вы можете наложить это заклинание, не тратя ячейку заклинания, и вы должны закончить продолжительный отдых, прежде чем сможете снова наложить его таким образом. Вы также можете наложить это заклинание, используя любые имеющиеся у вас ячейки заклинаний.\nМагия рун. Вы знаете количество рун равное половине вашего бонуса мастерства (округляя в меньшую сторону) на ваш выбор из таблицы «Рунические заклинания» (Руна — заклинание): Враг — маскировка; Гора — опутывание; Дракон — цветной шарик; Друг — разговор с животными; Огонь — огненные ладони; Облако — туманное облако; Камень — убежище; Король — приказ; Путешествие — скороход; Смерть — нанесение ран; Холм — чудо-ягоды; Холод — доспех Агатиса; Шторм — волна грома.\nЕщё: вы также можете вызвать руну, отмеченную на предмете, и наложить её заклинание без ячейки заклинаний и материальных компонентов (после этого — продолжительный отдых). Базовая характеристика — Интеллект, Мудрость или Харизма (выбирается при взятии черты). При получении уровня вы можете заменить одну из известных рун.", "picks": [{"key": "spellAbility", "kind": "ability", "label": "Базовая характеристика черты", "options": ["int", "wis", "cha"]}, {"key": "rune", "kind": "option", "label": "Руна (количество рун = половина бонуса мастерства, округляя вниз; сейчас выберите одну)", "options": [{"id": "disguise-self", "label": "Враг — маскировка", "spell": "disguise-self"}, {"id": "entangle", "label": "Гора — опутывание", "spell": "entangle"}, {"id": "chromatic-orb", "label": "Дракон — цветной шарик", "spell": "chromatic-orb"}, {"id": "speak-with-animals", "label": "Друг — разговор с животными", "spell": "speak-with-animals"}, {"id": "burning-hands", "label": "Огонь — огненные ладони", "spell": "burning-hands"}, {"id": "fog-cloud", "label": "Облако — туманное облако", "spell": "fog-cloud"}, {"id": "sanctuary", "label": "Камень — убежище", "spell": "sanctuary"}, {"id": "command", "label": "Король — приказ", "spell": "command"}, {"id": "longstrider", "label": "Путешествие — скороход", "spell": "longstrider"}, {"id": "inflict-wounds", "label": "Смерть — нанесение ран", "spell": "inflict-wounds"}, {"id": "goodberry", "label": "Холм — чудо-ягоды", "spell": "goodberry"}, {"id": "armor-of-agathys", "label": "Холод — доспех Агатиса", "spell": "armor-of-agathys"}, {"id": "thunderwave", "label": "Шторм — волна грома", "spell": "thunderwave"}]}], "grant": {"spells": [{"id": "comprehend-languages", "use": "long"}]}, "cards": [{"name": "Магия рун", "desc": "Вы знаете количество рун, равное половине вашего бонуса мастерства (округляя вниз), из таблицы «Рунические заклинания». Каждый раз, когда вы заканчиваете продолжительный отдых, вы можете пометить известными вам рунами одно немагическое оружие, доспех, часть одежды или другой предмет, к которому вы прикасаетесь. Вы временно изучаете заклинания 1-го уровня, основанные на начертанных рунах, пока не окончите следующий продолжительный отдых. Пока вы носите или несёте помеченный предмет, вы можете накладывать эти заклинания, используя ячейки. Кроме того, вы можете вызвать руну и наложить её заклинание без ячейки и материальных компонентов — не более одного раза за продолжительный отдых. Базовая характеристика: {ability}. Каждый раз, когда вы получаете уровень, вы можете заменить одну из известных рун."}], "runePick": true}, {"id": "soul-of-the-storm-giant", "name": "Душа штормового великана", "nameEn": "Soul of the storm giant", "source": "Bigby Presents: Glory of the Giants", "prereq": "4 уровень, черта «Удар Великанов (Штормовой удар)»", "desc": "Вы проявили магию бури, характерную для штормовых великанов, что дает вам следующие преимущества:\nУвеличение характеристик. Увеличьте значение Силы, Мудрости или Харизмы на 1 при максимуме 20.\nАура водоворота. Бонусным действием вы окружаете себя аурой магического ветра и молнии, которая простирается на 10 футов от вас во всех направлениях, но не через полное укрытие. Аура длится до начала вашего следующего хода или до тех пор, пока вы не станете недееспособны. Пока аура активна, вы получаете сопротивление урону звуком и электричеством. Так же броски атаки против вас совершаются с помехой, и всякий раз, когда существо начинает свой ход в пределах ауры, вы можете заставить его совершить спасбросок Силы (Сл равна 8 + ваш бонус мастерства + модификатор характеристики, увеличенной этой чертой). При провале скорость существа уменьшается вдвое до начала его следующего хода. Вы можете использовать это бонусное действие количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда заканчиваете продолжительный отдых.", "abilityIncrease": {"choices": ["str", "wis", "cha"], "amount": 1}, "cards": [{"name": "Аура водоворота", "desc": "Бонусным действием вы окружаете себя аурой магического ветра и молнии, которая простирается на 10 футов от вас во всех направлениях, но не через полное укрытие. Аура длится до начала вашего следующего хода или до тех пор, пока вы не станете недееспособны. Пока аура активна, вы получаете сопротивление урону звуком и электричеством. Так же броски атаки против вас совершаются с помехой, и всякий раз, когда существо начинает свой ход в пределах ауры, вы можете заставить его совершить спасбросок Силы (Сл равна 8 + ваш бонус мастерства + модификатор характеристики, увеличенной этой чертой). При провале скорость существа уменьшается вдвое до начала его следующего хода. Вы можете использовать это бонусное действие количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда заканчиваете продолжительный отдых."}]}, {"id": "guile-of-the-cloud-giant", "name": "Коварство облачного великана", "nameEn": "Guile of the cloud giant", "source": "Bigby Presents: Glory of the Giants", "prereq": "4 уровень, черта «Удар Великанов (Облачный удар)»", "desc": "Вы проявили сбивающую с толку магию, характерную для облачных великанов, что даёт вам следующие преимущества:\nУвеличение характеристик. Увеличьте значение Силы, Телосложения или Харизмы на 1 при максимуме 20.\nОблачный побег. Когда существо, которое вы видите, попадает по вам броском атаки, вы можете реакцией дать себе сопротивление урону от этой атаки. Затем вы телепортируетесь в свободное пространство, которое вы можете видеть в пределах 30 футов от себя. Вы можете использовать эту реакцию количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все израсходованные использования, когда заканчиваете продолжительный отдых.", "abilityIncrease": {"choices": ["str", "con", "cha"], "amount": 1}, "cards": [{"name": "Облачный побег", "desc": "Когда существо, которое вы видите, попадает по вам броском атаки, вы можете реакцией дать себе сопротивление урону от этой атаки. Затем вы телепортируетесь в свободное пространство, которое вы можете видеть в пределах 30 футов от себя. Вы можете использовать эту реакцию количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все израсходованные использования, когда заканчиваете продолжительный отдых."}]}, {"id": "fury-of-the-frost-giant", "name": "Неистовство ледяного великана", "nameEn": "Fury of the frost giant", "source": "Bigby Presents: Glory of the Giants", "prereq": "4 уровень, черта «Удар Великанов (Ледяной удар)»", "desc": "Вы проявляете ледяную мощь, характерную для ледяных великанов, что даёт вам следующие преимущества:\nУвеличение характеристик. Увеличьте значение Силы, Телосложения или Мудрости на 1 при максимуме 20.\nРождённый изо льда. Вы получаете сопротивление урону холодом.\nХолодное возмездие. Сразу же после того, как существо, которое вы можете видеть в пределах 30 футов от вас, попадает по вам броском атаки и наносит урон, вы можете реакцией нанести ответный удар сотворенным взрывом льда. Существо должно совершить спасбросок Телосложения (Сл равна 8 + ваш бонус мастерства + модификатор характеристики, увеличенной этой чертой). При провале оно получает 1к8 + ваш бонус мастерства урона холодом, а его скорость уменьшается до 0 до конца его следующего хода. Вы можете использовать эту реакцию количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все израсходованные использования, когда заканчиваете продолжительный отдых.", "abilityIncrease": {"choices": ["str", "con", "wis"], "amount": 1}, "cards": [{"name": "Рождённый изо льда", "desc": "Вы получаете сопротивление урону холодом."}, {"name": "Холодное возмездие", "desc": "Сразу же после того, как существо, которое вы можете видеть в пределах 30 футов от вас, попадает по вам броском атаки и наносит урон, вы можете реакцией нанести ответный удар сотворенным взрывом льда. Существо должно совершить спасбросок Телосложения (Сл равна 8 + ваш бонус мастерства + модификатор характеристики, увеличенной этой чертой). При провале оно получает 1к8 + ваш бонус мастерства урона холодом, а его скорость уменьшается до 0 до конца его следующего хода. Вы можете использовать эту реакцию количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все израсходованные использования, когда заканчиваете продолжительный отдых."}]}, {"id": "embar-of-the-fire-giant", "name": "Пылкость огненного великана", "nameEn": "Embar of the fire giant", "source": "Bigby Presents: Glory of the Giants", "prereq": "4 уровень, черта «Удар Великанов (Огненный удар)»", "desc": "Вы проявляете ярость битвы, характерную для огненных великанов, что даёт вам следующие преимущества:\nУвеличение характеристик. Увеличьте значение Силы, Телосложения или Мудрости на 1 при максимуме 20.\nРождённый пламенем. Вы получаете сопротивление урону огнём.\nПылающее воспламенение. Когда вы совершаете действие Атака в свой ход, вы можете заменить одну атаку магическим взрывом пламени. Каждое существо по вашему выбору в пределах сферы радиусом 15 футов с центром на вас должно совершить спасбросок Ловкости (Сл равна 8 + ваш бонус мастерства + модификатор характеристики, увеличенной этой чертой). При провале существо получает 1к8 + ваш бонус мастерства урона огнём и ослепляется до начала вашего следующего хода. При успехе существо получает только половину урона. Вы можете использовать «Пылающее воспламенение» количество раз, равное вашему бонусу мастерства (но не больше раза в ход), и вы восстанавливаете все израсходованные использования, когда заканчиваете продолжительный отдых.", "abilityIncrease": {"choices": ["str", "con", "wis"], "amount": 1}, "cards": [{"name": "Рождённый пламенем", "desc": "Вы получаете сопротивление урону огнём."}, {"name": "Пылающее воспламенение", "desc": "Когда вы совершаете действие Атака в свой ход, вы можете заменить одну атаку магическим взрывом пламени. Каждое существо по вашему выбору в пределах сферы радиусом 15 футов с центром на вас должно совершить спасбросок Ловкости (Сл равна 8 + ваш бонус мастерства + модификатор характеристики, увеличенной этой чертой). При провале существо получает 1к8 + ваш бонус мастерства урона огнём и ослепляется до начала вашего следующего хода. При успехе существо получает только половину урона. Вы можете использовать «Пылающее воспламенение» количество раз, равное вашему бонусу мастерства (но не больше раза в ход), и вы восстанавливаете все израсходованные использования, когда заканчиваете продолжительный отдых."}]}, {"id": "vigor-of-the-hill-giant", "name": "Стойкость холмового великана", "nameEn": "Vigor of the hill giant", "source": "Bigby Presents: Glory of the Giants", "prereq": "4 уровень, черта «Удар Великанов (Холмовой удар)»", "desc": "Вы проявили характерную для холмовых великанов стойкость, что дало вам следующие преимущества:\nУвеличение характеристик. Увеличьте значение Силы, Телосложения или Мудрости на 1 при максимуме 20.\nБастион. Когда вы подвергаетесь эффекту, который переместит вас как минимум на 5 футов или собьёт с ног, вы можете реакцией устоять на ногах. Тогда вы не будете ни сдвинуты, ни сбиты с ног.\nЖелезный желудок. Всякий раз, когда вы едите пищу во время короткого отдыха и тратите одну или несколько Костей Хитов, чтобы восстановить хиты, вы восстанавливаете дополнительные хиты, равные вашему модификатору Телосложения + вашему бонусу мастерства.", "abilityIncrease": {"choices": ["str", "con", "wis"], "amount": 1}, "cards": [{"name": "Бастион", "desc": "Когда вы подвергаетесь эффекту, который переместит вас как минимум на 5 футов или собьёт с ног, вы можете реакцией устоять на ногах. Тогда вы не будете ни сдвинуты, ни сбиты с ног."}, {"name": "Железный желудок", "desc": "Всякий раз, когда вы едите пищу во время короткого отдыха и тратите одну или несколько Костей Хитов, чтобы восстановить хиты, вы восстанавливаете дополнительные хиты, равные вашему модификатору Телосложения + вашему бонусу мастерства."}]}, {"id": "keenness-of-the-stone-giant", "name": "Чуткость каменного великана", "nameEn": "Keenness of the stone giant", "source": "Bigby Presents: Glory of the Giants", "prereq": "4 уровень, черта «Удар Великанов (Каменный удар)»", "desc": "Вы проявляете физические способности, характерные для каменных великанов, что даёт вам следующие преимущества:\nУвеличение характеристики. Увеличьте значение Силы, Телосложения или Мудрости на 1 при максимуме 20.\nГорное зрение. Вы получаете тёмное зрение в радиусе 60 футов. Если у вас уже есть тёмное зрение из другого источника, его диапазон увеличивается на 60 футов.\nБросок камня. Бонусным действием вы можете взять камень и совершить им магическую атаку. Эта атака является дальнобойной атакой заклинанием с дальностью 60 футов, которая в качестве базовой характеристики заклинаний использует ту, которую вы повысили при получении этой черты. При попадании камень наносит 1к10 урона силовым полем, и если цель существо, она должна преуспеть в спасброске Силы (Сл равна 8 + ваш бонус мастерства + модификатор базовой характеристики) или будет сбита с ног. Вы можете использовать это бонусное действие количество раз, равное вашему бонусу мастерства и вы восстанавливаете все израсходованные использования, когда заканчиваете продолжительный отдых.", "abilityIncrease": {"choices": ["str", "con", "wis"], "amount": 1}, "cards": [{"name": "Горное зрение", "desc": "Вы получаете тёмное зрение в радиусе 60 футов. Если у вас уже есть тёмное зрение из другого источника, его диапазон увеличивается на 60 футов."}, {"name": "Бросок камня", "desc": "Бонусным действием вы можете взять камень и совершить им магическую атаку. Эта атака является дальнобойной атакой заклинанием с дальностью 60 футов, которая в качестве базовой характеристики заклинаний использует ту, которую вы повысили при получении этой черты. При попадании камень наносит 1к10 урона силовым полем, и если цель существо, она должна преуспеть в спасброске Силы (Сл равна 8 + ваш бонус мастерства + модификатор базовой характеристики) или будет сбита с ног. Вы можете использовать это бонусное действие количество раз, равное вашему бонусу мастерства и вы восстанавливаете все израсходованные использования, когда заканчиваете продолжительный отдых."}]}, {"id": "strike-of-the-giants", "name": "Удар великанов", "nameEn": "Strike of the giants", "source": "Bigby Presents: Glory of the Giants", "prereq": "владение воинским оружием или предыстория «Великаний подкидыш»", "desc": "Вы впитали первобытную магию, дающую вам отголосок мощи великанов. Когда вы берёте эту черту, выберите одно из преимуществ ниже. Один раз в ход, когда вы попадаете по цели рукопашной атакой оружием или дальнобойной атакой метательным оружием, вы можете наделить атаку дополнительным эффектом, зависящим от выбранного вами преимущества:\nХолмовой удар. Цель получает дополнительно 1к6 урона того же вида, что и урон оружием. Если цель — существо, она должна преуспеть в спасброске Силы, иначе будет сбита с ног.\nКаменный удар. Цель получает дополнительно 1к6 урона силовым полем. Если цель — существо, она должна преуспеть в спасброске Силы, иначе будет оттолкнута от вас на 10 футов по прямой линии.\nЛедяной удар. Цель получает дополнительно 1к6 урона холодом. Если цель — существо, она должна преуспеть в спасброске Телосложения, иначе её скорость снижается до 0 до начала вашего следующего хода.\nОгненный удар. Цель получает дополнительно 1к10 урона огнём.\nОблачный удар. Цель получает дополнительно 1к4 урона звуком. Если цель — существо, она должна преуспеть в спасброске Мудрости, иначе вы станете невидимым для неё до начала вашего следующего хода или сразу после того, как вы совершите бросок атаки или наложите заклинание.\nШтормовой удар. Цель получает дополнительно 1к6 урона электричеством. Если цель — существо, она должна преуспеть в спасброске Телосложения, иначе она совершает с помехой броски атаки до начала вашего следующего хода.\nСл спасброска от этих эффектов равен 8 + ваш бонус мастерства + ваш модификатор Силы или Телосложения.\nВы можете использовать эту черту количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда заканчиваете продолжительный отдых.", "picks": [{"key": "strike", "kind": "option", "label": "Выберите преимущество", "options": [{"id": "hill", "label": "Холмовой удар", "card": {"name": "Удар великанов: Холмовой удар", "desc": "Один раз в ход, когда вы попадаете по цели рукопашной атакой оружием или дальнобойной атакой метательным оружием, вы можете наделить атаку дополнительным эффектом. Цель получает дополнительно 1к6 урона того же вида, что и урон оружием. Если цель — существо, она должна преуспеть в спасброске Силы, иначе будет сбита с ног. Сл спасброска равен 8 + ваш бонус мастерства + ваш модификатор Силы или Телосложения. Вы можете использовать эту черту количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда заканчиваете продолжительный отдых.", "rider": {"sides": 6, "count": 1, "note": "того же вида, что урон оружия; Сила или сбита с ног", "consume": true}}}, {"id": "stone", "label": "Каменный удар", "card": {"name": "Удар великанов: Каменный удар", "desc": "Один раз в ход, когда вы попадаете по цели рукопашной атакой оружием или дальнобойной атакой метательным оружием, вы можете наделить атаку дополнительным эффектом. Цель получает дополнительно 1к6 урона силовым полем. Если цель — существо, она должна преуспеть в спасброске Силы, иначе будет оттолкнута от вас на 10 футов по прямой линии. Сл спасброска равен 8 + ваш бонус мастерства + ваш модификатор Силы или Телосложения. Вы можете использовать эту черту количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда заканчиваете продолжительный отдых.", "rider": {"sides": 6, "count": 1, "note": "силовое поле; Сила или оттолкнута на 10 фт", "consume": true}}}, {"id": "frost", "label": "Ледяной удар", "card": {"name": "Удар великанов: Ледяной удар", "desc": "Один раз в ход, когда вы попадаете по цели рукопашной атакой оружием или дальнобойной атакой метательным оружием, вы можете наделить атаку дополнительным эффектом. Цель получает дополнительно 1к6 урона холодом. Если цель — существо, она должна преуспеть в спасброске Телосложения, иначе её скорость снижается до 0 до начала вашего следующего хода. Сл спасброска равен 8 + ваш бонус мастерства + ваш модификатор Силы или Телосложения. Вы можете использовать эту черту количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда заканчиваете продолжительный отдых.", "rider": {"sides": 6, "count": 1, "note": "холод; Телосложение или скорость 0", "consume": true}}}, {"id": "fire", "label": "Огненный удар", "card": {"name": "Удар великанов: Огненный удар", "desc": "Один раз в ход, когда вы попадаете по цели рукопашной атакой оружием или дальнобойной атакой метательным оружием, вы можете наделить атаку дополнительным эффектом. Цель получает дополнительно 1к10 урона огнём. Сл спасброска равен 8 + ваш бонус мастерства + ваш модификатор Силы или Телосложения. Вы можете использовать эту черту количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда заканчиваете продолжительный отдых.", "rider": {"sides": 10, "count": 1, "note": "огонь", "consume": true}}}, {"id": "cloud", "label": "Облачный удар", "card": {"name": "Удар великанов: Облачный удар", "desc": "Один раз в ход, когда вы попадаете по цели рукопашной атакой оружием или дальнобойной атакой метательным оружием, вы можете наделить атаку дополнительным эффектом. Цель получает дополнительно 1к4 урона звуком. Если цель — существо, она должна преуспеть в спасброске Мудрости, иначе вы станете невидимым для неё до начала вашего следующего хода или сразу после того, как вы совершите бросок атаки или наложите заклинание. Сл спасброска равен 8 + ваш бонус мастерства + ваш модификатор Силы или Телосложения. Вы можете использовать эту черту количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда заканчиваете продолжительный отдых.", "rider": {"sides": 4, "count": 1, "note": "звук; Мудрость или вы невидимы для неё", "consume": true}}}, {"id": "storm", "label": "Штормовой удар", "card": {"name": "Удар великанов: Штормовой удар", "desc": "Один раз в ход, когда вы попадаете по цели рукопашной атакой оружием или дальнобойной атакой метательным оружием, вы можете наделить атаку дополнительным эффектом. Цель получает дополнительно 1к6 урона электричеством. Если цель — существо, она должна преуспеть в спасброске Телосложения, иначе она совершает с помехой броски атаки до начала вашего следующего хода. Сл спасброска равен 8 + ваш бонус мастерства + ваш модификатор Силы или Телосложения. Вы можете использовать эту черту количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда заканчиваете продолжительный отдых.", "rider": {"sides": 6, "count": 1, "note": "электричество; Телосложение или помеха на атаки", "consume": true}}}]}]}, {"id": "cartomancer", "name": "Картомант", "nameEn": "Cartomancer", "source": "The Book of Many Things", "prereq": "4 уровень, умение «Использование заклинаний»", "desc": "Вы научились направлять свою магию через колоду игральных карт. Вы можете использовать колоду карт в качестве магической фокусировки.\nКарточные фокусы. Вы изучаете заговор фокусы [prestidigitation] и можете использовать его для создания иллюзий, дублирующих эффекты сценической магии. Когда вы используете фокусы таким образом, вы можете замаскировать вербальные и соматические компоненты заклинания как обыденную беседу и обращение с картами.\nТуз в рукаве. Когда вы заканчиваете продолжительный отдых, вы можете выбрать одно заклинание из списка вашего класса и вложить его в карту. Время накладывания выбранного заклинания должно быть «1 действие», и это должен быть уровень, для которого у вас есть ячейки заклинаний. Карта остаётся пропитанной этим заклинанием в течение 8 часов. Пока карта наполнена заклинанием, вы можете бонусным действием развернуть карту и наложить вложенное в неё заклинание. После этого карта сразу же теряет свою магию.", "grant": {"cantrips": ["prestidigitation"]}, "cards": [{"name": "Карточные фокусы", "desc": "Вы изучаете заговор «Фокусы» и можете использовать его для создания иллюзий, дублирующих эффекты сценической магии. Вы можете замаскировать вербальные и соматические компоненты заклинания как обыденную беседу и обращение с картами. Колода игральных карт — ваша магическая фокусировка."}, {"name": "Туз в рукаве", "desc": "Когда вы заканчиваете продолжительный отдых, вы можете выбрать одно заклинание из списка вашего класса со временем накладывания «1 действие» уровня, для которого у вас есть ячейки, и вложить его в карту на 8 часов. Пока карта наполнена, вы можете бонусным действием развернуть её и наложить заклинание; после этого карта теряет магию. Использование: раз в день, восстанавливается после продолжительного отдыха."}]}, {"id": "aberrant-dragonmark", "name": "Искажённая метка дракона", "nameEn": "Aberrant dragonmark", "source": "Eberron: Rising from the Last War", "prereq": "Отсутствие другой Метки Дракона", "desc": "Вы пробудили искажённую метку дракона. Определите её внешний вид и связанный с ней недостаток. Вы получаете следующие преимущества:\n• Увеличьте значение Телосложения на 1 при максимуме 20.\n• Вы узнаете заговор по своему выбору из списка заклинаний чародея. Кроме того, выберите одно заклинание 1-го уровня из этого же списка. Вы узнаете это заклинание и можете наложить его с помощью своей Метки. После использования заклинания, вы должны закончить короткий или продолжительный отдых, прежде чем сможете снова наложить его этой чертой. Телосложение является базовой характеристикой для этих заклинаний.\n• Когда вы используете заклинание 1-го уровня с помощью своей метки, вы можете потратить одну из своих костей хитов и бросить её. Если выпадает чётное число, то вы получаете временные хиты, равные результату броска. Если выпадает нечётное число, то одно случайное существо в радиусе 30 футов от вас (не считая вас) получает урон силовым полем, равный результату броска. Если в радиусе вокруг вас нет других существ, то вы получаете этот урон.\n• Вы также получаете случайный изъян из таблицы «Изъяны искажённой метки Дракона».\nИзъяны искажённой метки Дракона (к8): 1 — постоянная физическая боль; 2 — метка что-то шепчет; 3 — при стрессе метка громко шипит; 4 — кожа вокруг метки обгорела, покрылась чешуёй или засохла; 5 — животным неуютно рядом с вами; 6 — перепады настроения при использовании метки; 7 — внешний вид слегка меняется при использовании метки; 8 — кошмары после использования метки.", "abilityIncrease": {"choices": ["con"], "amount": 1}, "picks": [{"key": "cantrip", "kind": "spell", "label": "Заговор чародея", "level": 0, "count": 1, "cast": "cantrip", "lists": ["sorcerer"]}, {"key": "spell1", "kind": "spell", "label": "Заклинание 1-го уровня (чародей)", "level": 1, "count": 1, "cast": "free-any", "lists": ["sorcerer"]}], "grant": {"abilityFixed": "con"}, "cards": [{"name": "Искажённая метка: излишки силы", "desc": "Когда вы используете заклинание 1-го уровня с помощью своей метки, вы можете потратить одну из своих костей хитов и бросить её. Если выпадает чётное число, вы получаете временные хиты, равные результату. Если нечётное, одно случайное существо в радиусе 30 футов от вас (не считая вас) получает урон силовым полем, равный результату; если других существ нет, урон получаете вы. Вы также получаете случайный изъян из таблицы «Изъяны искажённой метки Дракона» (к8)."}]}, {"id": "revenant-blade", "name": "Призрачный клинок", "nameEn": "Revenant blade", "source": "Eberron: Rising from the Last War", "prereq": "Эльф", "desc": "Ваш предок был мастером двойного скимитара, и часть этого мастерства передалась вам. Вы получаете следующие преимущества:\n• Увеличьте значение вашей Силы или Ловкости на 1 при максимуме 20.\n• Когда вы держите двойной скимитар двумя руками, вы получаете бонус +1 к КД.\n• Когда вы орудуете двойным скимитаром, он обладает свойством «фехтовальное».\nДвойной скимитар — воинское оружие (6 фунтов, 2к4 рубящего урона, «двуручное»): после действия Атака вы можете бонусным действием совершить им рукопашную атаку, наносящую 1к4 рубящего урона.", "abilityIncrease": {"choices": ["str", "dex"], "amount": 1}, "grant": {"weaponItem": {"name": "Двойной скимитар", "damage": "2к4", "type": "руб.", "properties": "Двуручное, фехтовальное (черта «Призрачный клинок»); бонусная атака 1к4", "rangeType": "melee"}}, "cards": [{"name": "Призрачный клинок", "desc": "Когда вы держите двойной скимитар двумя руками, вы получаете бонус +1 к КД. Когда вы орудуете двойным скимитаром, он обладает свойством «фехтовальное». Двойной скимитар — воинское оружие (6 фунтов, 2к4 рубящего урона, свойство «двуручное»): если вы атакуете им, то сразу после Атаки можете бонусным действием совершить им рукопашную атаку, наносящую 1к4 рубящего урона."}]}, {"id": "gift-of-metallic-dragon", "name": "Дар металлического дракона", "nameEn": "Gift of metallic dragon", "source": "Fizban's Treasury of Dragons", "prereq": "", "desc": "Вы проявляете в себе некоторые силы металлического дракона, получая следующие преимущества:\n• Исцеление дракона. Вы изучаете заклинание лечение ран [cure wounds]. Вы можете накладывать это заклинание без затрат ячеек заклинаний. Как только вы накладываете это заклинание подобным образом, вам необходимо закончить продолжительный отдых, чтобы наложить его подобным образом вновь. Вы также можете накладывать это заклинание, используя любые имеющиеся у вас ячейки заклинаний. Интеллект, Мудрость или Харизма является вашей базовой характеристикой для этого заклинания (выберите одну из них при получении этой черты).\n• Защитные крылья. Вы можете расправить защитные крылья, которое защитят вас или других от атак. Когда по вам или другому существу, которое вы можете видеть в пределах 5 футов от вас, попадают броском атаки, вы можете реакцией расправить призрачные крылья за вашей спиной. Вы предоставляете бонус к КД цели, равный вашему бонусу мастерства, против этого броска атаки, что может привести к промаху. Вы можете использовать эту реакцию количество раз, равное вашему бонусу мастерства. Вы восстанавливаете все потраченные использования после окончания продолжительного отдыха.", "picks": [{"key": "spellAbility", "kind": "ability", "label": "Базовая характеристика «Исцеления дракона»", "options": ["int", "wis", "cha"]}], "grant": {"spells": [{"id": "cure-wounds", "use": "long"}]}, "cards": [{"name": "Защитные крылья", "desc": "Когда по вам или другому существу, которое вы видите в пределах 5 футов от вас, попадают броском атаки, вы можете реакцией расправить призрачные крылья: цель получает бонус к КД, равный вашему бонусу мастерства, против этого броска, что может привести к промаху. Вы можете использовать эту реакцию количество раз, равное вашему бонусу мастерства. Вы восстанавливаете все потраченные использования после окончания продолжительного отдыха."}]}, {"id": "gift-of-gem-dragon", "name": "Дар самоцветного дракона", "nameEn": "Gift of gem dragon", "source": "Fizban's Treasury of Dragons", "prereq": "", "desc": "Вы проявляете в себе некоторые силы самоцветного дракона, получая следующие преимущества:\n• Увеличение характеристик. Увеличьте значение вашего Интеллекта, Мудрости или Харизмы на 1, при максимуме 20.\n• Телекинетическое возмездие. Когда вы получаете урон от существа, которое находится в пределах 10 футов от вас, вы можете реакцией начать излучать телекинетическую энергию. Существо, которое причинило вам урон, должно совершить спасбросок Силы (Сл 8 + ваш бонус мастерства + ваш модификатор характеристики, которую вы увеличили этой чертой). При провале существо получает 2к8 урона силовым полем и отталкивается от вас на 10 футов. При успехе существо не отталкивается и получает половину урона. Вы можете использовать эту реакцию количество раз, равное вашему бонусу мастерства. Вы восстанавливаете все потраченные использования после окончания продолжительного отдыха.", "abilityIncrease": {"choices": ["int", "wis", "cha"], "amount": 1}, "cards": [{"name": "Телекинетическое возмездие", "desc": "Когда вы получаете урон от существа в пределах 10 футов от вас, вы можете реакцией начать излучать телекинетическую энергию. Существо должно совершить спасбросок Силы (Сл 8 + ваш бонус мастерства + модификатор характеристики, которую вы увеличили этой чертой). При провале оно получает 2к8 урона силовым полем и отталкивается от вас на 10 футов; при успехе — половину урона и не отталкивается. Вы можете использовать эту реакцию количество раз, равное вашему бонусу мастерства. Вы восстанавливаете все потраченные использования после окончания продолжительного отдыха."}]}, {"id": "gift-of-chromatic-dragon", "name": "Дар цветного дракона", "nameEn": "Gift of chromatic dragon", "source": "Fizban's Treasury of Dragons", "prereq": "", "desc": "Вы проявляете в себе некоторые силы цветного дракона, получая следующие преимущества:\n• Цветная инфузия. Бонусным действием вы касаетесь простого или воинского оружия и наполняете его одним из указанных ниже видов урона: кислота, огонь, электричество, холод или яд. В течение следующей минуты это оружие будет при попадании дополнительно наносить 1к4 урона выбранного вами вида. Как только вы используете это преимущество, вы не можете использовать его снова, пока не закончите продолжительный отдых.\n• Мгновенное сопротивление. Когда вы получаете урон кислотой, огнём, электричеством, холодом или ядом, вы можете реакцией получить сопротивление этой порции получаемого урона. Вы можете использовать эту реакцию количество раз, равное вашему бонусу мастерства. Вы восстанавливаете все потраченные использования после окончания продолжительного отдыха.", "cards": [{"name": "Цветная инфузия", "desc": "Бонусным действием вы касаетесь простого или воинского оружия и наполняете его одним из видов урона: кислота, огонь, электричество, холод или яд. В течение следующей минуты это оружие при попадании дополнительно наносит 1к4 урона выбранного вида. Как только вы используете это преимущество, вы не можете использовать его снова, пока не закончите продолжительный отдых.", "rider": {"sides": 4, "count": 1, "note": "кислота / огонь / электричество / холод / яд (на выбор)", "consume": true}}, {"name": "Мгновенное сопротивление", "desc": "Когда вы получаете урон кислотой, огнём, электричеством, холодом или ядом, вы можете реакцией получить сопротивление этой порции получаемого урона. Вы можете использовать эту реакцию количество раз, равное вашему бонусу мастерства. Вы восстанавливаете все потраченные использования после окончания продолжительного отдыха."}]}, {"id": "agent-of-order", "name": "Агент Порядка", "nameEn": "Agent of order", "source": "Planescape: Adventures in the Multiverse", "prereq": "4 уровень, черта «Наследник внешних планов (законный внешний план)»", "desc": "Вы можете направлять космические силы порядка, которые связывают мультивселенную в закономерности. Ваши действия зависят от вас, но эти силы дают вам следующие преимущества:\nУвеличение характеристик. Увеличьте значение характеристики по вашему выбору на 1 при максимуме 20.\nСтазисный удар. Один раз за ход, когда вы наносите урон существу, которое видите в пределах 60 футов от себя, вы можете нанести цели дополнительный 1к8 урона силовым полем и она должна преуспеть в спасброске Мудрости (Сл равна 8 + ваш бонус мастерства + модификатор базовой характеристики, выбранной при взятии черты «Наследник внешних планов»), потому что спектральные оковы пытаются поймать его. При успехе цель избегает этого. При провале цель становится опутаной до начала вашего следующего хода. Эти оковы проявляются в виде цепей или какого-либо другого символа стазиса. Вы можете использовать это преимущество количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда оканчиваете продолжительный отдых.", "abilityIncrease": {"choices": ["str", "dex", "con", "int", "wis", "cha"], "amount": 1}, "cards": [{"name": "Стазисный удар", "desc": "Один раз за ход, когда вы наносите урон существу, которое видите в пределах 60 футов от себя, вы можете нанести цели дополнительный 1к8 урона силовым полем и она должна преуспеть в спасброске Мудрости (Сл равна 8 + ваш бонус мастерства + модификатор базовой характеристики, выбранной при взятии черты «Наследник внешних планов»), потому что спектральные оковы пытаются поймать его. При успехе цель избегает этого. При провале цель становится опутаной до начала вашего следующего хода. Эти оковы проявляются в виде цепей или какого-либо другого символа стазиса. Вы можете использовать это преимущество количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда оканчиваете продолжительный отдых.", "rider": {"sides": 8, "count": 1, "note": "силовое поле, цель в пределах 60 фт; Мудрость или опутана", "consume": true}}]}, {"id": "baleful-scion", "name": "Зловещий наследник", "nameEn": "Baleful scion", "source": "Planescape: Adventures in the Multiverse", "prereq": "4 уровень, «Наследник внешних планов (злой внешний план)»", "desc": "Вы можете направлять космические силы зла, которые причиняют боль, но укрепляют ваше существо. Вы можете выбирать свои собственные действия, несмотря на эту пагубную связь. Вы получаете следующие преимущества:\nУвеличение характеристик. Увеличьте значение характеристики по вашему выбору на 1 при максимуме 20.\nХватка Алчности. Один раз за ход, когда вы наносите видимому вами существу в пределах 60 футов от вас урон, вы также можете нанести ему урон некротической энергией. Урон равен 1к6 + ваш бонус мастерства, и вы восстанавливаете количество хитов, равное нанесённому некротическому урону. Вы можете использовать это преимущество количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все израсходованные использования, когда завершаете продолжительный отдых.", "abilityIncrease": {"choices": ["str", "dex", "con", "int", "wis", "cha"], "amount": 1}, "cards": [{"name": "Хватка Алчности", "desc": "Один раз за ход, когда вы наносите видимому вами существу в пределах 60 футов от вас урон, вы также можете нанести ему урон некротической энергией. Урон равен 1к6 + ваш бонус мастерства, и вы восстанавливаете количество хитов, равное нанесённому некротическому урону. Вы можете использовать это преимущество количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все израсходованные использования, когда завершаете продолжительный отдых.", "rider": {"sides": 6, "count": 1, "flatPb": true, "note": "некротическая энергия + бонус мастерства; вы восстанавливаете столько же хитов", "consume": true}}]}, {"id": "cohort-of-chaos", "name": "Когорта Хаоса", "nameEn": "Cohort of chaos", "source": "Planescape: Adventures in the Multiverse", "prereq": "4 уровень, «Наследник внешних планов (хаотичный внешний план)»", "desc": "Вы можете направить космические силы хаоса, чтобы получить следующие преимущества:\nУвеличение характеристик. Увеличьте значение характеристики по вашему выбору на 1 при максимуме 20.\nХаотическая вспышка. Когда вы выбрасываете «1» или «20» при броске атаки или спасброске, магия хаоса течёт через вас. Совершите бросок по таблице «Хаотические вспышки», чтобы определить, что произойдет. Вспышка длится до конца вашего следующего хода, а новая вспышка не может появиться до тех пор, пока не закончится первая вспышка.\nХаотические вспышки (к4): 1 — Боевая ярость. 2 — Поле разрушения. 3 — Свободный. 4 — Воющие ветры.", "abilityIncrease": {"choices": ["str", "dex", "con", "int", "wis", "cha"], "amount": 1}, "cards": [{"name": "Хаотическая вспышка", "desc": "Когда вы выбрасываете «1» или «20» при броске атаки или спасброске, магия хаоса течёт через вас. Совершите бросок к4: 1 — Боевая ярость (существо по вашему выбору, которое вы видите, совершает броски атаки с преимуществом, а проверки характеристик с помехой); 2 — Поле разрушения (каждое существо, начинающее ход в пределах 5 футов от вас или впервые входящее туда за ход, получает 1к8 урона силовым полем); 3 — Свободный (при движении вы можете один раз телепортироваться на расстояние до своей скорости в видимое свободное пространство); 4 — Воющие ветры (вы и существа в сфере радиусом 15 футов совершаете спасброски Мудрости с помехой). Вспышка длится до конца вашего следующего хода; новая вспышка не может появиться, пока не закончится первая."}]}, {"id": "scion-of-the-outer-planes", "name": "Наследник внешних планов", "nameEn": "Scion of the outer planes", "source": "Planescape: Adventures in the Multiverse", "prereq": "кампания в сеттинге «Planescape»", "desc": "Ваша связь с Внешним планом наполняет вас энергией этого места. Выберите план, указанный в таблице «Планарное влияние». Ваш выбор даёт вам сопротивление виду урона и возможность накладывать заговор, указанный в таблице. Вы можете наложить этот заговор без материальных компонентов, а вашей базовой характеристикой для него является Интеллект, Мудрость или Харизма (выберите, когда выбираете эту черту).\nПланарное влияние: Хаотичный Внешний план: яд; Злой Внешний план: некротическая энергия; Добрый Внешний план: излучение; Законный Внешний план: силовое поле; Внешние земли: психическая энергия", "picks": [{"key": "spellAbility", "kind": "ability", "label": "Базовая характеристика заговора", "options": ["int", "wis", "cha"]}, {"key": "plane", "kind": "option", "label": "Внешний план (даёт сопротивление и заговор)", "options": [{"id": "chaos", "label": "Хаотичный Внешний план — сопротивление: Яд", "cantrip": "minor-illusion", "card": {"name": "Планарное влияние: Хаотичный Внешний план", "desc": "Вы получаете сопротивление урону вида «яд». Вы можете накладывать выбранный заговор без материальных компонентов; базовая характеристика — {ability}."}}, {"id": "evil", "label": "Злой Внешний план — сопротивление: Некротическая энергия", "cantrip": "chill-touch", "card": {"name": "Планарное влияние: Злой Внешний план", "desc": "Вы получаете сопротивление урону вида «некротическая энергия». Вы можете накладывать выбранный заговор без материальных компонентов; базовая характеристика — {ability}."}}, {"id": "good", "label": "Добрый Внешний план — сопротивление: Излучение", "cantrip": "sacred-flame", "card": {"name": "Планарное влияние: Добрый Внешний план", "desc": "Вы получаете сопротивление урону вида «излучение». Вы можете накладывать выбранный заговор без материальных компонентов; базовая характеристика — {ability}."}}, {"id": "law", "label": "Законный Внешний план — сопротивление: Силовое поле", "cantrip": "guidance", "card": {"name": "Планарное влияние: Законный Внешний план", "desc": "Вы получаете сопротивление урону вида «силовое поле». Вы можете накладывать выбранный заговор без материальных компонентов; базовая характеристика — {ability}."}}, {"id": "outlands", "label": "Внешние земли — сопротивление: Психическая энергия", "cantrip": "mage-hand", "card": {"name": "Планарное влияние: Внешние земли", "desc": "Вы получаете сопротивление урону вида «психическая энергия». Вы можете накладывать выбранный заговор без материальных компонентов; базовая характеристика — {ability}."}}]}]}, {"id": "planar-wanderer", "name": "Планарный странник", "nameEn": "Planar wanderer", "source": "Planescape: Adventures in the Multiverse", "prereq": "4 уровень, черта «Наследник внешних планов»", "desc": "Вы можете использовать силы мультивселенной, чтобы выжить в космических экстремальных условиях и пересечь её бесконечные миры. Вы получаете следующие преимущества:\nПланарная адаптация. Когда вы оканчиваете продолжительный отдых, вы получаете сопротивление урону кислотой, холодом или огнём (на ваш выбор), пока не окончите следующий продолжительный отдых.\nВзломщик порталов. Ваш опыт работы с порталами позволяет вам управлять ими без соответствующего ключа портала. Действием вы можете сконцентрироваться на известном вам портале, который находится в пределах 5 футов от вас и совершить проверку Интеллекта (Магия) Сл 20. При провале вы получаете 3к8 урона силовым полем и не можете снова использовать эту черту на этом портале, пока не окончите продолжительный отдых. При успехе вы можете принудительно открыть или закрыть портал на 1 час. В течение этого времени портал, закрытый таким образом, не отвечает на свой ключ портала, если существо, использующее ключ, действием не преуспеет в проверке Интеллекта (Магия) Сл 20.\nЧувство порталов. Вы знаете направление к последнему планарному порталу, который вы использовали, пока вы и портал находитесь на одном плане. Кроме того, действием вы можете обнаружить местоположение любых порталов в пределах 30 футов от вас, которые не находятся за полным укрытием. Как только вы обнаружите портал этим действием, вы не сможете использовать это действие снова, пока не окончите продолжительный отдых.", "cards": [{"name": "Планарная адаптация", "desc": "Когда вы оканчиваете продолжительный отдых, вы получаете сопротивление урону кислотой, холодом или огнём (на ваш выбор), пока не окончите следующий продолжительный отдых."}, {"name": "Взломщик порталов", "desc": "Ваш опыт работы с порталами позволяет вам управлять ими без соответствующего ключа портала. Действием вы можете сконцентрироваться на известном вам портале, который находится в пределах 5 футов от вас и совершить проверку Интеллекта (Магия) Сл 20. При провале вы получаете 3к8 урона силовым полем и не можете снова использовать эту черту на этом портале, пока не окончите продолжительный отдых. При успехе вы можете принудительно открыть или закрыть портал на 1 час. В течение этого времени портал, закрытый таким образом, не отвечает на свой ключ портала, если существо, использующее ключ, действием не преуспеет в проверке Интеллекта (Магия) Сл 20."}, {"name": "Чувство порталов", "desc": "Вы знаете направление к последнему планарному порталу, который вы использовали, пока вы и портал находитесь на одном плане. Кроме того, действием вы можете обнаружить местоположение любых порталов в пределах 30 футов от вас, которые не находятся за полным укрытием. Как только вы обнаружите портал этим действием, вы не сможете использовать это действие снова, пока не окончите продолжительный отдых."}]}, {"id": "outlands-envoy", "name": "Посол Внешних земель", "nameEn": "Outlands envoy", "source": "Planescape: Adventures in the Multiverse", "prereq": "4 уровень, «Наследник внешних планов (Внешние земли)»", "desc": "Вы провели много времени в Сигиле или где-то ещё во Внешних землях, на перекрестке мультивселенной. Погружение в сходящиеся планарные энергии даёт вам следующие преимущества:\nУвеличение характеристик. Увеличьте значение характеристики по вашему выбору на 1 при максимуме 20.\nЭмиссар перекрёстка. Вы изучаете заклинания туманный шаг [misty step] и языки [tongues]. Вы можете наложить каждое заклинание один раз, используя это умение без затрат ячеек заклинаний, и вы должны окончить продолжительный отдых, прежде чем вы сможете снова наложить это заклинание таким образом. Когда вы накладываете языки [tongues], используя эту черту, вам не требуются материальные компоненты. Вы также можете накладывать эти заклинания, используя имеющиеся у вас ячейки заклинаний соответствующего уровня. Базовая характеристика для этих заклинаний выбирается, когда вы получаете черту «Наследник внешних планов».", "abilityIncrease": {"choices": ["str", "dex", "con", "int", "wis", "cha"], "amount": 1}, "picks": [{"key": "spellAbility", "kind": "ability", "label": "Базовая характеристика заклинаний", "options": ["int", "wis", "cha"]}], "grant": {"spells": [{"id": "misty-step", "use": "long"}, {"id": "tongues", "use": "long"}]}}, {"id": "righteous-heritor", "name": "Праведный наследник", "nameEn": "Righteous heritor", "source": "Planescape: Adventures in the Multiverse", "prereq": "4 уровень, черта «Наследник внешних планов (добрый внешний план)»", "desc": "Вы можете направить космические силы добра, чтобы получить следующие преимущества:\nУвеличение характеристик. Увеличьте значение характеристики по вашему выбору на 1 при максимуме 20.\nУспокоить боль. Когда вы или существо, которое вы можете видеть в пределах 30 футов от вас, получает урон, вы можете реакцией смягчить его страдания и уменьшить получаемый им урон на 1к10 + ваш бонус мастерства. Вы можете использовать это преимущество количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все израсходованные использования, когда оканчиваете продолжительный отдых.", "abilityIncrease": {"choices": ["str", "dex", "con", "int", "wis", "cha"], "amount": 1}, "cards": [{"name": "Успокоить боль", "desc": "Когда вы или существо, которое вы можете видеть в пределах 30 футов от вас, получает урон, вы можете реакцией смягчить его страдания и уменьшить получаемый им урон на 1к10 + ваш бонус мастерства. Вы можете использовать это преимущество количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все израсходованные использования, когда оканчиваете продолжительный отдых."}]}, {"id": "svirfneblin-magic", "name": "Магия свирфнеблинов", "nameEn": "Svirfneblin magic", "source": "Sword Coast Adventurer's Guide", "prereq": "Гном (глубинный гном)", "desc": "Вы унаследовали врождённую способность к магии от своих предков. Она позволяет вам накладывать на себя заклинание необнаружимость [nondetection] по желанию и без надобности использовать материальные компоненты. Вы также можете однократно наложить следующие заклинания: глухота/слепота [blindness/deafness], размытый образ [blur] и маскировка [disguise self]. Вы восстанавливаете возможность накладывать эти заклинания закончив продолжительный отдых. Интеллект является базовой характеристикой для накладывания всех этих заклинаний.", "grant": {"abilityFixed": "int", "spells": [{"id": "nondetection", "use": "atwill"}, {"id": "blindnessdeafness", "use": "long"}, {"id": "blur", "use": "long"}, {"id": "disguise-self", "use": "long"}]}}, {"id": "metamagic-adept", "name": "Адепт метамагии", "nameEn": "Metamagic adept", "source": "Tasha's Cauldron of Everything", "prereq": "умение «Использование заклинаний» или «Магия договора»", "desc": "Вы научились управлять заклинаниями собственной волей, чтобы изменять их действие:\n• Вы узнаёте два варианта метамагии по вашему выбору из класса чародея. Вы можете использовать только один вариант метамагии для изменения заклинания, когда вы его накладываете, если только описание метамагии не говорит об обратном. Каждый раз, когда вы достигаете уровня и получаете умение «Увеличение характеристик», вы можете заменить одну из этих метамагий на другую из класса чародея.\n• Вы получаете 2 единицы чародейства для траты их на метамагию (эти единицы добавляются к любым единицам чародейства, которые вы получили из других источников, но могут быть использованы только для метамагии). Вы восстанавливаете все использованные единицы чародейства после окончания продолжительного отдыха.", "picks": [{"key": "meta", "kind": "metamagic", "label": "Два варианта метамагии", "count": 2}], "cards": [{"name": "Очки чародейства (Адепт метамагии)", "desc": "У вас есть 2 единицы чародейства, которые можно тратить только на метамагию (добавляются к очкам из других источников). 2/продолжительный отдых: вы восстанавливаете все использованные единицы после продолжительного отдыха."}]}, {"id": "eldritch-adept", "name": "Адепт таинств", "nameEn": "Eldritch adept", "source": "Tasha's Cauldron of Everything", "prereq": "умение «Использование заклинаний» или «Магия договора»", "desc": "Изучая оккультные знания, вы узнаёте одно из таинственных воззваний из класса колдуна по вашему выбору.\nВашей базовой заклинательной характеристикой для этого воззвания может быть Интеллект, Мудрость или Харизма (вы выбираете, когда берёте эту черту). Если у воззвания имеется требование любого вида, то вы можете выбрать это воззвание, только если вы колдун, который соответствует этому требованию.\nКаждый раз, когда вы получаете уровень, вы можете заменить воззвание другим из класса колдуна.", "picks": [{"key": "spellAbility", "kind": "ability", "label": "Базовая характеристика воззвания", "options": ["int", "wis", "cha"]}, {"key": "invocation", "kind": "invocation", "label": "Таинственное воззвание колдуна"}]}, {"id": "shadow-touched", "name": "Затронутый тенью", "nameEn": "Shadow touched", "source": "Tasha's Cauldron of Everything", "prereq": "", "desc": "Ваше взаимодействие с магией Царства Теней изменило вас, даровав вам следующие преимущества:\n• Увеличьте значение вашего Интеллекта, Мудрости или Харизмы на 1 при максимуме 20.\n• Вы узнаёте заклинание невидимость [invisibility] и одно заклинание 1-го уровня по вашему выбору. Заклинание 1-го уровня должно принадлежать школе Иллюзии или Некромантии. Вы можете накладывать каждое из этих заклинаний без затрат ячеек заклинаний. Как только вы накладываете любое из этих заклинаний подобным образом, вам необходимо закончить продолжительный отдых, чтобы наложить это заклинание подобным образом вновь. Вы также можете накладывать эти заклинания, используя любые имеющиеся у вас ячейки заклинаний подходящего уровня. Базовой характеристикой для этих заклинаний является та, которую вы увеличили данной чертой.", "abilityIncrease": {"choices": ["int", "wis", "cha"], "amount": 1}, "picks": [{"key": "spell1", "kind": "spell", "label": "Заклинание 1-го уровня (Иллюзия или Некромантия)", "level": 1, "count": 1, "cast": "free-long", "schools": ["Иллюзия", "Некромантия"]}], "grant": {"spells": [{"id": "invisibility", "use": "long"}]}}, {"id": "fey-touched", "name": "Затронутый феями", "nameEn": "Fey touched", "source": "Tasha's Cauldron of Everything", "prereq": "", "desc": "Ваше взаимодействие с магией Страны Фей изменило вас, даровав вам следующие преимущества:\n• Увеличьте значение вашего Интеллекта, Мудрости или Харизмы на 1 при максимуме 20.\n• Вы узнаёте заклинание туманный шаг [misty step] и одно заклинание 1-го уровня на ваш выбор. Заклинание 1-го уровня должно принадлежать школе Прорицания или Очарования. Вы можете накладывать каждое из этих заклинаний без затрат ячеек заклинаний. Как только вы накладываете любое из этих заклинаний подобным образом, вам необходимо закончить продолжительный отдых, чтобы наложить это заклинание подобным образом вновь. Вы также можете накладывать эти заклинания, используя любые имеющиеся у вас ячейки заклинаний подходящего уровня. Базовой характеристикой для этих заклинаний является та, которую вы увеличили данной чертой.", "abilityIncrease": {"choices": ["int", "wis", "cha"], "amount": 1}, "picks": [{"key": "spell1", "kind": "spell", "label": "Заклинание 1-го уровня (Прорицание или Очарование)", "level": 1, "count": 1, "cast": "free-long", "schools": ["Прорицание", "Очарование"]}], "grant": {"spells": [{"id": "misty-step", "use": "long"}]}}, {"id": "gunner", "name": "Знаток огнестрельного оружия", "nameEn": "Gunner", "source": "Tasha's Cauldron of Everything", "prereq": "", "desc": "Ваша рука быстра, а глаз остр, когда вопрос касается огнестрельного оружия, именно это и дарует вам следующие преимущества:\n• Увеличьте значение вашей Ловкости на 1, при максимуме 20.\n• Вы получаете владение огнестрельным оружием (см. раздел «Огнестрельное оружие» в «Руководстве мастера»).\n• Вы игнорируете свойство «перезарядка» у огнестрельного оружия.\n• Наличие противника в пределах 5 футов от вас не накладывает помехи на ваши броски дальнобойных атак.", "abilityIncrease": {"choices": ["dex"], "amount": 1}, "grant": {"weapons": ["Огнестрельное оружие"]}, "cards": [{"name": "Знаток огнестрельного оружия", "desc": "Вы игнорируете свойство «перезарядка» у огнестрельного оружия. Наличие противника в пределах 5 футов от вас не накладывает помеху на ваши броски дальнобойных атак."}]}, {"id": "crusher", "name": "Крушитель", "nameEn": "Crusher", "source": "Tasha's Cauldron of Everything", "prereq": "", "desc": "Вы практиковались в искусстве сокрушения врагов, что даёт вам следующие преимущества:\n• Увеличьте значение вашей Силы или Телосложения на 1 при максимуме 20.\n• Один раз в ход, когда вы попадаете по существу атакой, которая наносит дробящий урон, вы можете переместить цель на 5 футов в свободное пространство при условии, что цель больше вас не более чем на один размер.\n• Когда вы совершаете критический удар, который наносит дробящий урон существу, броски атаки по этому существу совершаются с преимуществом до начала вашего следующего хода.", "abilityIncrease": {"choices": ["str", "con"], "amount": 1}, "cards": [{"name": "Крушитель", "desc": "Один раз в ход, когда вы попадаете по существу атакой, которая наносит дробящий урон, вы можете переместить цель на 5 футов в свободное пространство (цель не больше вас более чем на один размер). Когда вы совершаете критический удар, наносящий дробящий урон, броски атаки по этому существу совершаются с преимуществом до начала вашего следующего хода."}]}, {"id": "poisoner", "name": "Отравитель", "nameEn": "Poisoner", "source": "Tasha's Cauldron of Everything", "prereq": "", "desc": "Вы можете изготавливать и применять смертельные яды, получая следующие преимущества:\n• Когда вы совершаете бросок урона для нанесения урона ядом, он игнорирует сопротивление урону ядом.\n• Вы можете наносить яд на оружие или боеприпасы бонусным действием, а не действием.\n• Вы получаете владение инструментами отравителя, если вы ими ещё не владеете. За один час работы с помощью инструментов отравителя, расходуя материалы на 50 зм, вы можете создать количество доз сильнодействующего яда, равное вашему бонусу мастерства. После нанесения этого яда на оружие или боеприпасы яд сохраняет свою силу в течение 1 минуты или до тех пор, пока вы не попадете атакой этим оружием или боеприпасами. Когда существо получает урон от отравленного оружия или отравленных боеприпасов, оно должно преуспеть в спасброске Телосложения Сл 14, иначе получит 2к8 урона ядом и станет отравленным до конца вашего следующего хода.", "grant": {"tools": ["Набор отравителя"]}, "cards": [{"name": "Отравитель", "desc": "Когда вы совершаете бросок урона ядом, он игнорирует сопротивление урону ядом. Вы можете наносить яд на оружие или боеприпасы бонусным действием. За 1 час работы с набором отравителя и расходом материалов на 50 зм вы создаёте количество доз сильнодействующего яда, равное вашему бонусу мастерства. Яд сохраняет силу 1 минуту или до попадания: существо должно преуспеть в спасброске Телосложения Сл 14, иначе получит 2к8 урона ядом и станет отравленным до конца вашего следующего хода."}]}, {"id": "fighting-initiate", "name": "Посвящённый в боевое искусство", "nameEn": "Fighting initiate", "source": "Tasha's Cauldron of Everything", "prereq": "владение хотя бы одним воинским оружием", "desc": "Ваши боевые тренировки помогли вам разработать особый стиль боя. Теперь вам известен один вариант боевого стиля по вашему выбору из класса воина. Если вам уже известен боевой стиль, то вы должны выбрать стиль, отличный от вашего.\nКаждый раз, когда вы достигаете определённого уровня и получаете умение «Увеличение характеристик», вы можете заменить боевой стиль от этой черты на другой из класса воина, который вы не знаете.", "picks": [{"key": "style", "kind": "fightstyle", "label": "Боевой стиль воина"}]}, {"id": "artificer-initiate", "name": "Посвящённый в изобретательство", "nameEn": "Artificer initiate", "source": "Tasha's Cauldron of Everything", "prereq": "", "desc": "Вы обучились некоторым изобретательским хитростям:\n• Вы узнаёте один заговор по вашему выбору из списка заклинаний изобретателя, и вы узнаёте одно заклинание 1-го уровня по вашему выбору из этого же списка. Базовой  заклинательной характеристикой для этих заклинаний является Интеллект.\n• Вы можете накладывать заклинание 1-го уровня, которое вы узнали от этой черты, без использования ячеек заклинаний, и должны закончить продолжительный отдых, прежде чем сможете снова воспользоваться этой особенностью. Вы можете также накладывать это заклинание, используя любые имеющиеся у вас ячейки заклинаний.\n• Вы получаете владение одним из инструментов ремесленника по вашему выбору и можете использовать этот инструмент в качестве заклинательной фокусировки для тех заклинаний, которые вы накладываете, используя Интеллект в качестве базовой характеристики.", "picks": [{"key": "cantrip", "kind": "spell", "label": "Заговор изобретателя", "level": 0, "count": 1, "cast": "cantrip", "lists": ["artificer"]}, {"key": "spell1", "kind": "spell", "label": "Заклинание 1-го уровня изобретателя", "level": 1, "count": 1, "cast": "free-long", "lists": ["artificer"]}, {"key": "tool", "kind": "tool", "label": "Инструмент ремесленника", "count": 1, "group": "artisan"}], "grant": {"abilityFixed": "int"}, "cards": [{"name": "Посвящённый в изобретательство", "desc": "Выбранный инструмент ремесленника можно использовать как заклинательную фокусировку для заклинаний, использующих Интеллект как базовую характеристику."}]}, {"id": "piercer", "name": "Пронзатель", "nameEn": "Piercer", "source": "Tasha's Cauldron of Everything", "prereq": "", "desc": "Вы достигли пронизывающей точности в бою, что даёт вам следующие преимущества:\n• Увеличьте значение вашей Силы или Ловкости на 1 при максимуме 20.\n• Один раз в ход, когда вы попадаете по существу атакой, которая наносит колющий урон, вы можете перебросить одну из костей урона, и должны использовать новый результат.\n• Когда вы наносите существу критический удар, причиняющий колющий урон, то после определения нанесенного критическим ударом урона вы можете добавить к нему дополнительно ещё одну из костей урона, наносящих колющий урон.", "abilityIncrease": {"choices": ["str", "dex"], "amount": 1}, "cards": [{"name": "Пронзатель", "desc": "Один раз в ход, когда вы попадаете по существу атакой, наносящей колющий урон, вы можете перебросить одну из костей урона и должны использовать новый результат. Когда вы наносите существу критический удар, причиняющий колющий урон, вы можете добавить к нему ещё одну кость колющего урона."}]}, {"id": "slasher", "name": "Рубака", "nameEn": "Slasher", "source": "Tasha's Cauldron of Everything", "prereq": "", "desc": "Вы узнали, где необходимо резать, чтобы получить наилучшие результаты, что даёт вам следующие преимущества:\n• Увеличьте значение вашей Силы или Ловкости на 1 при максимуме 20.\n• Один раз в ход, когда вы попадаете по существу атакой, которая наносит рубящий урон, вы можете уменьшить скорость цели на 10 футов до начала вашего следующего хода.\n• Когда вы наносите критический удар, причиняющий рубящий урон существу, вы тяжело раните цель. До начала вашего следующего хода цель совершает все свои броски атак с помехой.", "abilityIncrease": {"choices": ["str", "dex"], "amount": 1}, "cards": [{"name": "Рубака", "desc": "Один раз в ход, когда вы попадаете по существу атакой, наносящей рубящий урон, вы можете уменьшить скорость цели на 10 футов до начала вашего следующего хода. Когда вы наносите критический удар, причиняющий рубящий урон, цель совершает все броски атаки с помехой до начала вашего следующего хода."}]}, {"id": "telekinetic", "name": "Телекинетик", "nameEn": "Telekinetic", "source": "Tasha's Cauldron of Everything", "prereq": "", "desc": "Вы научились передвигать вещи силой своего разума, что даёт вам следующие преимущества:\n• Увеличьте значение вашего Интеллекта, Мудрости или Харизмы на 1 при максимуме 20.\n• Вы узнаёте заговор волшебная рука [mage hand]. Вы можете накладывать его без вербальных или соматических компонентов, и вы можете делать призрачную руку невидимой. Если вы уже знаете этот заговор, то его дистанция увеличивается на 30 футов, когда вы его накладываете. Базовой характеристикой этого заклинания является та, которую вы увеличили данной чертой.\n• Бонусным действием вы можете попытаться телекинетически толкнуть одно существо, которое вы можете видеть в пределах 30 футов. Когда вы это делаете, цель должна преуспеть в спасброске Силы (Сл 8 + ваш бонус мастерства + модификатор характеристики, которую вы увеличили данной чертой), иначе будет перемещена на 5 футов к вам или от вас. Существо может добровольно провалить этот спасбросок.", "abilityIncrease": {"choices": ["int", "wis", "cha"], "amount": 1}, "grant": {"cantrips": ["mage-hand"]}, "cards": [{"name": "Телекинетический толчок", "desc": "Бонусным действием вы можете телекинетически толкнуть одно существо, которое видите в пределах 30 футов. Цель должна преуспеть в спасброске Силы (Сл 8 + ваш бонус мастерства + модификатор характеристики, которую вы увеличили этой чертой), иначе будет перемещена на 5 футов к вам или от вас. Существо может добровольно провалить спасбросок."}, {"name": "Волшебная рука (Телекинетик)", "desc": "Вы можете накладывать «Волшебную руку» без вербальных и соматических компонентов и можете делать призрачную руку невидимой. Если вы уже знаете этот заговор, его дистанция увеличивается на 30 футов. Базовая характеристика — та, которую вы увеличили этой чертой."}]}, {"id": "telepathic", "name": "Телепат", "nameEn": "Telepathic", "source": "Tasha's Cauldron of Everything", "prereq": "", "desc": "Вы пробуждаете способность мысленно связываться с другими существами, что даёт вам следующие преимущества:\n• Увеличьте значение вашего Интеллекта, Мудрости или Харизмы на 1 при максимуме 20.\n• Вы можете телепатически общаться с любым существом, которое вы можете видеть в пределах 60 футов. Ваши телепатические высказывания произносятся на языке, который вы знаете, и существо понимает вас, только если оно знает этот язык. Ваше общение не даёт существу возможность отвечать вам телепатически.\n• Вы можете наложить заклинание обнаружение мыслей [detect thoughts] без использования ячеек заклинания или компонентов, и вы должны закончить продолжительный отдых, прежде чем сможете наложить его снова подобным образом. Базовой характеристикой этого заклинания является та, которую вы увеличили данной чертой. Если у вас есть ячейки заклинаний 2-го уровня или выше, вы можете накладывать это заклинание, используя эти ячейки.", "abilityIncrease": {"choices": ["int", "wis", "cha"], "amount": 1}, "grant": {"spells": [{"id": "detect-thoughts", "use": "long"}]}, "cards": [{"name": "Телепатическая связь", "desc": "Вы можете телепатически общаться с любым существом, которое видите в пределах 60 футов, на языке, который вы знаете (существо понимает вас только если знает этот язык). Ваше общение не даёт существу возможности отвечать телепатически."}]}, {"id": "chef", "name": "Шеф-повар", "nameEn": "Chef", "source": "Tasha's Cauldron of Everything", "prereq": "", "desc": "Время, потраченное на овладение кулинарным искусством, окупилось, предоставив вам следующие преимущества:\n• Увеличьте значение вашего Телосложения или Мудрости на 1 при максимуме 20.\n• Вы получаете владение инструментами повара, если вы ими ещё не владеете.\n• Во время короткого отдыха вы можете приготовить особую еду при условии, что у вас есть необходимые ингредиенты и инструменты повара под рукой. Вы можете приготовить достаточно пищи для количества существ, равного 4 + ваш бонус мастерства. В конце короткого отдыха любое существо, которое съедает эту пищу и тратит одну или несколько костей хитов, чтобы восстановить хиты, дополнительно восстанавливает 1к8 хитов.\n• За один час работы или по окончании продолжительного отдыха вы можете заготовить количество порций еды, равное вашему бонусу мастерства. Эти особые порции съедобны в течение 8 часов после приготовления. Существо может бонусным действием съесть одну из этих порций, чтобы получить количество временных хитов, равное вашему бонусу мастерства.", "abilityIncrease": {"choices": ["con", "wis"], "amount": 1}, "grant": {"tools": ["Инструменты повара"]}, "cards": [{"name": "Особая еда (короткий отдых)", "desc": "Во время короткого отдыха вы можете приготовить особую еду для количества существ, равного 4 + ваш бонус мастерства. Существо, которое съедает эту пищу и тратит одну или несколько костей хитов, дополнительно восстанавливает 1к8 хитов."}, {"name": "Гостинцы", "desc": "За один час работы или по окончании продолжительного отдыха вы можете заготовить количество порций еды, равное вашему бонусу мастерства. Порции съедобны 8 часов; существо может бонусным действием съесть порцию и получить количество временных хитов, равное вашему бонусу мастерства."}]}, {"id": "skill-expert", "name": "Эксперт в навыке", "nameEn": "Skill expert", "source": "Tasha's Cauldron of Everything", "prereq": "", "desc": "Вы отточили своё мастерство в использовании определённых умений, что даёт вам следующие преимущества:\n• Увеличьте значение одной вашей характеристики по вашему выбору на 1 при максимуме 20.\n• Вы получаете владение одним навыком на ваш выбор.\n• Выберите один навык, которым вы владеете. Вы получаете компетентность в этом навыке, что означает, что ваш бонус мастерства удваивается для всех проверок характеристик, использующих этот навык. Вы не можете выбрать навык, бонус мастерства для которого уже удвоен таким умением, как «Компетентность».", "abilityIncrease": {"choices": ["str", "dex", "con", "int", "wis", "cha"], "amount": 1}, "picks": [{"key": "skill", "kind": "skill", "label": "Новый навык (владение)", "count": 1}, {"key": "expertise", "kind": "skill", "label": "Навык с компетентностью (из тех, которыми вы владеете)", "count": 1, "expertise": true}]}, {"id": "bountiful-luck", "name": "Бездонная удача", "nameEn": "Bountiful luck", "source": "Xanathar's Guide to Everything", "prereq": "Полурослик", "desc": "Ваш народ обладает исключительной удачей, которой вы научились мистическим образом делиться со своими компаньонами, когда вы видите, что они не справляются. Вы не понимаете, как это работает, вы просто хотите, и это происходит. Определённо это знак покровительства удачи!\nКогда союзник, которого вы видите в пределах 30 футов от вас, выбрасывает «1» на к20 для броска атаки, проверки характеристик или спасброска, вы можете реакцией позволить союзнику перебросить кубик. Союзник обязан использовать новый результат.\nПосле использования этой способности вы не можете использовать вашу расовую особенность «Везучий» до конца вашего следующего хода.", "cards": [{"name": "Бездонная удача", "desc": "Когда союзник, которого вы видите в пределах 30 футов, выбрасывает «1» на к20 для броска атаки, проверки характеристики или спасброска, вы можете реакцией позволить ему перебросить кубик (он обязан использовать новый результат). После использования вы не можете использовать расовую особенность «Везучий» до конца вашего следующего хода."}]}, {"id": "second-chance", "name": "Второй шанс", "nameEn": "Second chance", "source": "Xanathar's Guide to Everything", "prereq": "Полурослик", "desc": "Удача улыбается вам, когда кто-то пытается ударить вас. Вы получаете следующие преимущества:\n• Увеличьте значение вашей Ловкости, Телосложения или Харизмы на 1 при максимуме 20.\n• Когда существо, которое вы видите, попадает по вам броском атаки, вы можете реакцией заставить врага перебросить этот бросок. После применения этой способности вы не сможете использовать её вновь до броска инициативы в начале боя либо пока не закончите короткий или продолжительный отдых.", "abilityIncrease": {"choices": ["dex", "con", "cha"], "amount": 1}, "cards": [{"name": "Второй шанс", "desc": "Когда существо, которое вы видите, попадает по вам броском атаки, вы можете реакцией заставить его перебросить этот бросок. После этого вы не сможете использовать эту способность до броска инициативы в начале боя либо пока не закончите короткий или продолжительный отдых."}]}, {"id": "prodigy", "name": "Вундеркинд", "nameEn": "Prodigy", "source": "Xanathar's Guide to Everything", "prereq": "Полуэльф, Полуорк или Человек", "desc": "У вас дар к освоению новых знаний. Вы получаете следующие преимущества:\n• Вы получаете владение одним навыком на выбор, владение одним набором инструментов на выбор и обучаетесь бегло говорить на одном языке на выбор.\n• Выберите один навык, которым уже владеете. Вы получаете компетентность в этом навыке, что удваивает ваш бонус мастерства для любой проверки характеристик с использованием этого навыка.Навык, который вы выбираете, не может уже получать удвоенный бонус мастерства от другого умения, такого как «Компетентность».", "picks": [{"key": "skill", "kind": "skill", "label": "Владение навыком", "count": 1}, {"key": "tool", "kind": "tool", "label": "Владение набором инструментов", "count": 1}, {"key": "language", "kind": "language", "label": "Язык", "count": 1}, {"key": "expertise", "kind": "skill", "label": "Компетентность в навыке, которым вы владеете", "count": 1, "expertise": true}]}, {"id": "drow-high-magic", "name": "Высшая магия дроу", "nameEn": "Drow high magic", "source": "Xanathar's Guide to Everything", "prereq": "Эльф (дроу)", "desc": "Вы изучаете магию, присущую тёмным эльфам.\nВы изучаете заклинание обнаружение магии [detect magic] и можете свободно накладывать его без затрат ячеек заклинаний. Вы также изучаете заклинания левитация [levitate] и рассеивание магии [dispel magic], каждое из которых вы можете наложить один раз без затрат ячеек заклинаний. Вы восстанавливаете возможность накладывать эти два заклинания таким способом после продолжительного отдыха. Харизма – базовая характеристика для этих трёх заклинаний.", "grant": {"abilityFixed": "cha", "spells": [{"id": "detect-magic", "use": "atwill"}, {"id": "levitate", "use": "long"}, {"id": "dispel-magic", "use": "long"}]}}, {"id": "dwarven-fortitude", "name": "Дварфийская стойкость", "nameEn": "Dwarven Fortitude", "source": "Xanathar's Guide to Everything", "prereq": "Дварф", "desc": "В ваших венах течёт кровь героев дварфов. Вы получаете следующие преимущества:\n• Увеличьте значение вашего Телосложения на 1 при максимуме 20.\n• Когда в битве вы совершаете действие Уклонение, вы можете потратить Кость Хитов чтобы вылечить себя. Бросьте кость, добавьте модификатор Телосложения и восстановите хиты в количестве, равном полученному значению (минимум 1).", "abilityIncrease": {"choices": ["con"], "amount": 1}, "cards": [{"name": "Дварфийская стойкость", "desc": "Когда в битве вы совершаете действие Уклонение, вы можете потратить Кость Хитов, чтобы вылечить себя: бросьте кость, добавьте модификатор Телосложения и восстановите хиты в количестве, равном полученному значению (минимум 1)."}]}, {"id": "dragon-fear", "name": "Драконий страх", "nameEn": "Dragon fear", "source": "Xanathar's Guide to Everything", "prereq": "Драконорождённый", "desc": "Когда вы злитесь, то излучаете угрозу. Вы получаете следующие преимущества:\n• Увеличьте значение вашей Силы, Телосложения или Харизмы на 1 при максимуме 20.\n• Вместо выдоха разрушительной энергии, вы можете использовать вашу особенность «Оружие дыхания», чтобы издать рык, заставляя всех выбранных вами существ в пределах 30 футов от вас сделать спасбросок Мудрости (Сл 8 + бонус мастерства + модификатор Харизмы). Цель автоматически проходит спасбросок, если она не может слышать или видеть вас. При провале броска цель становится напуганной вами на 1 минуту. Если напуганная цель получает урон, то она может повторить спасбросок, оканчивая эффект на себе при успехе.", "abilityIncrease": {"choices": ["str", "con", "cha"], "amount": 1}, "cards": [{"name": "Драконий страх", "desc": "Вместо выдоха разрушительной энергии вы можете использовать «Оружие дыхания», чтобы издать рык: все выбранные вами существа в пределах 30 футов делают спасбросок Мудрости (Сл 8 + бонус мастерства + модификатор Харизмы); цель автоматически преуспевает, если не может слышать или видеть вас. При провале цель становится напуганной вами на 1 минуту; если напуганная цель получает урон, она может повторить спасбросок, оканчивая эффект на себе при успехе."}]}, {"id": "dragon-hide", "name": "Драконья шкура", "nameEn": "Dragon hide", "source": "Xanathar's Guide to Everything", "prereq": "Драконорождённый", "desc": "У вас появляются чешуя и когти, напоминающие таковые у вашего драконьего предка. Вы получаете следующие преимущества:\n• Увеличьте значение вашей Силы, Телосложения или Харизмы на 1 при максимуме 20.\n• Ваша чешуя становится твёрже. Пока вы не носите броню, ваш КД равен 13 + модификатор Ловкости. Вы можете использовать щит, продолжая получать это преимущество.\n• Вы отращиваете втягивающиеся когти на кончиках ваших пальцев. Вытягивание или втягивание их не требует траты каких-либо действий. Эти когти являются природным оружием, которым вы можете совершать безоружные удары. Если вы попадете такой атакой, то наносите 1к4 + модификатор Силы рубящего урона вместо обычного дробящего урона для безоружного удара.", "abilityIncrease": {"choices": ["str", "con", "cha"], "amount": 1}, "grant": {"attack": {"name": "Когти (Драконья шкура)", "damage": "1к4 руб.", "rangeType": "melee", "ability": "str"}}, "cards": [{"name": "Драконья шкура", "desc": "Пока вы не носите броню, ваш КД равен 13 + модификатор Ловкости (можно использовать щит). Вы отращиваете втягивающиеся когти — природное оружие для безоружных ударов: при попадании они наносят 1к4 + модификатор Силы рубящего урона вместо дробящего. Вытягивание и втягивание когтей не требует действий."}]}, {"id": "infernal-constitution", "name": "Инфернальное телосложение", "nameEn": "Infernal constitution", "source": "Xanathar's Guide to Everything", "prereq": "Тифлинг", "desc": "Кровь исчадий сильна в вас и даёт вам сопротивления, которыми обладают некоторые исчадия. Вы получаете следующие преимущества:\n• Увеличьте значение вашего Телосложения на 1 при максимуме 20.\n• Вы получаете сопротивление урону холодом и ядом.\n• Вы получаете преимущество на спасброски против эффектов, делающих вас отравленным.", "abilityIncrease": {"choices": ["con"], "amount": 1}, "cards": [{"name": "Инфернальное телосложение", "desc": "Вы получаете сопротивление урону холодом и ядом, а также преимущество на спасброски против эффектов, делающих вас отравленным."}]}, {"id": "fade-away", "name": "Исчезновение", "nameEn": "Fade away", "source": "Xanathar's Guide to Everything", "prereq": "Гном", "desc": "Ваш народ искусно владеет магией иллюзий. Вы выучили магический трюк, чтобы исчезать, когда вам наносят урон. Вы получаете следующие преимущества:\n• Увеличьте значение вашей Ловкости или Интеллекта на 1 при максимуме 20.\n• Сразу же после получения урона вы можете реакцией стать невидимым до конца своего следующего хода, либо пока не совершите атаку, не нанесёте урон или не заставите кого-нибудь совершать спасбросок. Использовав эту черту, вы не сможете использовать её вновь, пока не совершите короткий или продолжительный отдых.", "abilityIncrease": {"choices": ["dex", "int"], "amount": 1}, "cards": [{"name": "Исчезновение", "desc": "Сразу же после получения урона вы можете реакцией стать невидимым до конца своего следующего хода либо пока не совершите атаку, не нанесёте урон или не заставите кого-нибудь совершать спасбросок. Использовав это умение, вы не сможете использовать его вновь, пока не совершите короткий или продолжительный отдых."}]}, {"id": "wood-elf-magic", "name": "Магия лесных эльфов", "nameEn": "Wood elf magic", "source": "Xanathar's Guide to Everything", "prereq": "Эльф (лесной)", "desc": "Вы изучаете магию первобытных лесов, которые почитаются и защищаются вашим народом. Вы изучаете один заговор друида на ваш выбор. Вы также изучаете заклинания скороход [longstrider] и бесследное передвижение [pass without trace], каждое из которых вы можете наложить один раз не тратя ячейку заклинаний. Вы восстанавливаете возможность накладывать их таким образом в конце продолжительного отдыха. Мудрость – базовая характеристика для этих трёх заклинаний.", "picks": [{"key": "cantrip", "kind": "spell", "label": "Заговор друида", "level": 0, "count": 1, "cast": "cantrip", "lists": ["druid"]}], "grant": {"abilityFixed": "wis", "spells": [{"id": "longstrider", "use": "long"}, {"id": "pass-without-trace", "use": "long"}]}}, {"id": "squat-nimbleness", "name": "Низкорослое проворство", "nameEn": "Squat nimbleness", "source": "Xanathar's Guide to Everything", "prereq": "Дварф или Маленькая раса", "desc": "Вы необычайно проворны для вашей расы. Вы получаете следующие выгоды:\n• Увеличьте значение вашей Силы или Ловкости на 1 при максимуме 20.\n• Ваша скорость увеличивается на 5 футов.\n• Вы получаете владение навыком Акробатика или Атлетика (на ваш выбор).\n• Вы получаете преимущество на броски Силы (Атлетика) или Ловкости (Акробатика), которые делаете, чтобы выбраться из захвата.", "abilityIncrease": {"choices": ["str", "dex"], "amount": 1}, "picks": [{"key": "skill", "kind": "option", "label": "Владение навыком", "options": [{"id": "acrobatics", "label": "Акробатика", "skill": "acrobatics"}, {"id": "athletics", "label": "Атлетика", "skill": "athletics"}]}], "cards": [{"name": "Низкорослое проворство", "desc": "Ваша скорость увеличивается на 5 футов. Вы получаете преимущество на проверки Силы (Атлетика) или Ловкости (Акробатика), которые делаете, чтобы выбраться из захвата."}]}, {"id": "orcish-fury", "name": "Орочье буйство", "nameEn": "Orcish fury", "source": "Xanathar's Guide to Everything", "prereq": "Полуорк", "desc": "Ваша ярость неутомимо горит внутри вас. Вы получаете следующие преимущества:\n• Увеличьте значение вашей Силы или Телосложения на 1 при максимуме 20.\n• Когда вы попадаете атакой простым или воинским оружием, вы можете кинуть одну кость оружия ещё раз и добавить результат в качестве дополнительного урона того же типа, что и у оружия. Использовав это преимущество, вы не можете использовать его вновь, пока не закончите короткий или продолжительный отдых.\n• Сразу же после использования особенности «Непоколебимая стойкость» вы можете реакцией совершить одну атаку оружием.", "abilityIncrease": {"choices": ["str", "con"], "amount": 1}, "cards": [{"name": "Орочье буйство: дополнительная кость", "desc": "Когда вы попадаете атакой простым или воинским оружием, вы можете кинуть одну кость оружия ещё раз и добавить результат как дополнительный урон того же типа. Использовав это преимущество, вы не можете использовать его вновь, пока не закончите короткий или продолжительный отдых."}, {"name": "Орочье буйство: ответная атака", "desc": "Сразу же после использования особенности «Непоколебимая стойкость» вы можете реакцией совершить одну атаку оружием."}]}, {"id": "flames-of-phlegethos", "name": "Пламя Флегетоса", "nameEn": "Flames of Phlegethos", "source": "Xanathar's Guide to Everything", "prereq": "Тифлинг", "desc": "Вы научились призывать адский огонь, и он вас слушается. Вы получаете следующие преимущества:\n• Увеличьте значение вашего Интеллекта или Харизмы на 1 при максимуме 20.\n• Когда вы делаете бросок урона огнём, который наносит ваше заклинание, вы можете перебросить любые «1» на костях урона огнём, но должны использовать новые результаты, даже если они тоже будут «1».\n• Когда вы накладываете заклинание, которое наносит урон огнём, вы можете заставить пламя окутать вас до конца вашего следующего хода. Пламя не причиняет урон вам и вашим вещам, а также излучает яркий свет на 30 футов и тусклый свет ещё на 30 футов. Пока пламя существует, любое существо в пределах 5 футов получают 1к4 урона огнём, если попадают по вам рукопашной атакой.", "abilityIncrease": {"choices": ["int", "cha"], "amount": 1}, "cards": [{"name": "Пламя Флегетоса: переброс", "desc": "Когда вы делаете бросок урона огнём, который наносит ваше заклинание, вы можете перебросить любые «1» на костях урона огнём, но должны использовать новые результаты, даже если они тоже «1»."}, {"name": "Пламя Флегетоса: огненный покров", "desc": "Когда вы накладываете заклинание, наносящее урон огнём, вы можете заставить пламя окутать вас до конца вашего следующего хода. Пламя не причиняет вреда вам и вашим вещам, излучает яркий свет на 30 футов и тусклый ещё на 30 футов. Пока пламя существует, любое существо в пределах 5 футов, попавшее по вам рукопашной атакой, получает 1к4 урона огнём."}]}, {"id": "fey-teleportation", "name": "Телепортация фей", "nameEn": "Fey teleportation", "source": "Xanathar's Guide to Everything", "prereq": "Эльф (высший)", "desc": "Изучение знаний высших эльфов открыло вам силу фей, которой владеют немногие эльфы, за исключением ваших собратьев эладринов. Опираясь на свое родство с феями, вы можете на мгновение пройти через Страну Фей, сократив свой путь. Вы получаете следующие преимущества:\n• Увеличьте значение вашего Интеллекта или Харизмы на 1 при максимуме 20.\n• Вы изучаете как читать, говорить и писать на Сильване.\n• Вы изучаете заклинание туманный шаг [misty step] и можете наложить его один раз без использования ячейки заклинания. Вы восстанавливаете возможность накладывать его таким образом, когда завершаете короткий или продолжительный отдых. Интеллект – базовая характеристика для этого заклинания.", "abilityIncrease": {"choices": ["int", "cha"], "amount": 1}, "grant": {"abilityFixed": "int", "languages": ["Сильванский"], "spells": [{"id": "misty-step", "use": "any"}]}}, {"id": "elven-accuracy", "name": "Эльфийская точность", "nameEn": "Elven accuracy", "source": "Xanathar's Guide to Everything", "prereq": "Эльф или Полуэльф", "desc": "Точность эльфов легендарна, особенно это касается эльфийских лучников и заклинателей. Вы обладаете сверхъестественной меткостью, когда дело касается атак, требующих меткости, а не грубой силы. Вы получаете следующие преимущества:\n• Увеличьте значение вашей Ловкости, Интеллекта, Мудрости или Харизмы на 1 при максимуме 20.\n• Когда вы совершаете с преимуществом бросок атаки, использующий Ловкость, Интеллект, Мудрость или Харизму, вы можете перебросить одну из костей один раз.", "abilityIncrease": {"choices": ["dex", "int", "wis", "cha"], "amount": 1}, "cards": [{"name": "Эльфийская точность", "desc": "Когда вы совершаете с преимуществом бросок атаки, использующий Ловкость, Интеллект, Мудрость или Харизму, вы можете перебросить одну из костей один раз."}]}, {"id": "adept-of-the-white-robes", "name": "Адепт Белых одежд", "nameEn": "Adept of the White Robes", "source": "Dragonlance: Shadow of the Dragon Queen", "prereq": "4 уровень, черта «Посвящённый в Высшее волшебство» (Солинари)", "desc": "Вы выбрали луну Солинари, чтобы влиять на свою магию, и ваша клятва использовать магию, чтобы сделать мир лучше, была признана Орденом Белых одежд, предоставляя вам следующие преимущества:\nЗащитная магия. Вы изучаете одно заклинание 2-го уровня на ваш выбор. Заклинание 2-го уровня должно быть из школы ограждения или прорицания. Вы можете наложить заклинание 2-го уровня этого умения без ячейки заклинания, и вы должны завершить продолжительный отдых, прежде чем снова сможете наложить его таким образом. Вы также можете наложить это заклинание, используя имеющиеся у вас ячейки заклинаний соответствующего уровня. Базовая характеристика выбирается, когда вы получаете черту «Посвящённый в Высшее Чародейство».\nЗащитная палата. Когда вы или существо, которое вы можете видеть в пределах 30 футов от вас, получает урон, вы можете реакцией потратить ячейку заклинания и окружить цель защитной магией. Бросьте количество к6, равное уровню израсходованной ячейки заклинания, и уменьшите урон, получаемый целью, на сумму бросков на этих костях + ваш модификатор базовой характеристики.", "picks": [{"key": "spellAbility", "kind": "ability", "label": "Базовая характеристика (как у «Посвящённого в Высшее волшебство»)", "options": ["int", "wis", "cha"]}, {"key": "spell2", "kind": "spell", "label": "Заклинание 2-го уровня (Ограждение или Прорицание)", "level": 2, "count": 1, "cast": "free-long", "schools": ["Ограждение", "Прорицание"]}], "cards": [{"name": "Защитная палата", "desc": "Когда вы или существо, которое вы можете видеть в пределах 30 футов от вас, получает урон, вы можете реакцией потратить ячейку заклинания и окружить цель защитной магией. Бросьте количество к6, равное уровню израсходованной ячейки заклинания, и уменьшите урон, получаемый целью, на сумму бросков на этих костях + ваш модификатор базовой характеристики."}]}, {"id": "adept-of-the-red-robes", "name": "Адепт Красных одежд", "nameEn": "Adept of the Red Robes", "source": "Dragonlance: Shadow of the Dragon Queen", "prereq": "4 уровень, черта «Посвящённый в Высшее волшебство» (Лунитари)", "desc": "Вы выбрали луну Лунитари, чтобы влиять на свою магию, и ваша приверженность поддержанию баланса между всеми вещами была признана Орденом Красных одежд, предоставляя вам следующие преимущества:\nПроницательная магия. Вы изучаете одно заклинание 2-го уровня на ваш выбор. Заклинание 2-го уровня должно быть из школы магии иллюзии или преобразования. Вы можете наложить заклинание 2-го уровня этой черты без траты ячейки заклинания, и вы должны завершить продолжительный отдых, прежде чем снова сможете наложить его таким образом. Вы также можете наложить это заклинание, используя имеющиеся у вас ячейки заклинаний соответствующего уровня. Базовая характеристика выбирается, когда вы получаете черту «Посвящение в Высшее волшебство».\nМагический баланс. Когда вы совершаете бросок атаки или проверку характеристики и выбрасываете «9» или меньше на к20, вы можете сбалансировать судьбу и рассматривать бросок как 10. Вы можете сбалансировать судьбу таким образом количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда заканчиваете продолжительный отдых.", "picks": [{"key": "spellAbility", "kind": "ability", "label": "Базовая характеристика (как у «Посвящённого в Высшее волшебство»)", "options": ["int", "wis", "cha"]}, {"key": "spell2", "kind": "spell", "label": "Заклинание 2-го уровня (Иллюзия или Преобразование)", "level": 2, "count": 1, "cast": "free-long", "schools": ["Иллюзия", "Преобразование"]}], "cards": [{"name": "Магический баланс", "desc": "Когда вы совершаете бросок атаки или проверку характеристики и выбрасываете «9» или меньше на к20, вы можете сбалансировать судьбу и рассматривать бросок как 10. Вы можете сбалансировать судьбу таким образом количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда заканчиваете продолжительный отдых."}]}, {"id": "adept-of-the-black-robes", "name": "Адепт Чёрных одежд", "nameEn": "Adept of the Black Robes", "source": "Dragonlance: Shadow of the Dragon Queen", "prereq": "4 уровень, черта «Посвящённый в Высшее волшебство» (Нуитари)", "desc": "Вы выбрали луну Нуитари, чтобы влиять на свою магию, и ваши амбиции и лояльность к Ордену Чёрных одежд были признаны, предоставляя вам следующие преимущества:\nАмбициозная магия. Вы изучаете одно заклинание 2-го уровня на ваш выбор. Заклинание 2-го уровня должно быть из школы очарования или некромантии. Вы можете наложить заклинание 2-го уровня от этой черты без траты ячейки заклинания, и вы должны завершить продолжительный отдых, прежде чем снова сможете наложить его таким образом. Вы также можете наложить это заклинание, используя имеющиеся у вас ячейки заклинаний соответствующего уровня. Базовая характеристика выбирается, когда вы получаете черту «Посвящённый в Высшее чародейство».\nКанал Жизни. Вы можете направить свою жизненную силу в силу своей магии. Когда существо, которое вы можете видеть в пределах 60 футов от вас, проваливает спасбросок от заклинания, наносящего урон, которое вы накладываете, вы можете потратить количество костей хитов, равное уровню заклинания. Бросьте использованные кости хитов и сложите их. Урон, который получает существо, увеличивается на получившуюся сумму.", "picks": [{"key": "spellAbility", "kind": "ability", "label": "Базовая характеристика (как у «Посвящённого в Высшее волшебство»)", "options": ["int", "wis", "cha"]}, {"key": "spell2", "kind": "spell", "label": "Заклинание 2-го уровня (Очарование или Некромантия)", "level": 2, "count": 1, "cast": "free-long", "schools": ["Очарование", "Некромантия"]}], "cards": [{"name": "Канал Жизни", "desc": "Вы можете направить свою жизненную силу в силу своей магии. Когда существо, которое вы можете видеть в пределах 60 футов от вас, проваливает спасбросок от заклинания, наносящего урон, которое вы накладываете, вы можете потратить количество костей хитов, равное уровню заклинания. Бросьте использованные кости хитов и сложите их. Урон, который получает существо, увеличивается на получившуюся сумму."}]}, {"id": "divinely-favored", "name": "Любимец богов", "nameEn": "Divinely Favored", "source": "Dragonlance: Shadow of the Dragon Queen", "prereq": "4 уровень, кампания «Саге о Копье»", "desc": "Божество выбрало вас, чтобы нести искру своей силы.\nВы изучаете один заговор по вашему выбору из списка заклинаний жреца и одно заклинание 1-го уровня, основанное на мировоззрении вашего персонажа, как указано в таблице «Заклинания мировоззрения»: Злое — одно заклинание колдуна 1-го уровня; Доброе — одно заклинание жреца 1-го уровня; Нейтральное — одно заклинание друида 1-го уровня.\nВы можете наложить выбранное заклинание 1-го уровня и заклинание гадание [augury] без ячейки заклинания, и вы должны закончить продолжительный отдых, прежде чем сможете снова наложить любое из этих заклинаний таким же образом. Вы также можете накладывать эти заклинания, используя имеющиеся у вас ячейки заклинаний соответствующего уровня.\nВашей базовой характеристикой для заклинаний от этой черты — Интеллект, Мудрость или Харизма (выберите, когда вы выбираете эту черту).\nКроме того, вы можете использовать священный символ в качестве фокусировки заклинаний для любых заклинаний, которые используют базовую характеристику, определённую при выборе этой черты.", "picks": [{"key": "spellAbility", "kind": "ability", "label": "Базовая характеристика заклинаний", "options": ["int", "wis", "cha"]}, {"key": "cantrip", "kind": "spell", "label": "Заговор жреца", "level": 0, "count": 1, "cast": "cantrip", "lists": ["cleric"]}, {"key": "align", "kind": "option", "label": "Мировоззрение (определяет список заклинания 1-го уровня)", "options": [{"id": "evil", "label": "Злое — список колдуна"}, {"id": "good", "label": "Доброе — список жреца"}, {"id": "neutral", "label": "Нейтральное — список друида"}]}, {"key": "spell1", "kind": "spell", "label": "Заклинание 1-го уровня по мировоззрению", "level": 1, "count": 1, "cast": "free-long", "byKey": "align", "map": {"evil": {"lists": ["warlock"]}, "good": {"lists": ["cleric"]}, "neutral": {"lists": ["druid"]}}}], "grant": {"spells": [{"id": "augury", "use": "long"}]}, "cards": [{"name": "Любимец богов", "desc": "Вы можете использовать священный символ как фокусировку заклинаний для заклинаний, использующих базовую характеристику, определённую при выборе этой черты."}]}, {"id": "squire-of-solamnia", "name": "Оруженосец рыцаря Соламнии", "nameEn": "Squire of Solamnia", "source": "Dragonlance: Shadow of the Dragon Queen", "prereq": "кампания «Саге о Копье»; Воин или Паладин или предыстория «Соламнийский Рыцарь»", "desc": "Ваше обучение путям Соламнийских Рыцарей даёт вам следующие преимущества:\nПосадка в седло. Посадка в седло и спешивание стоит вам всего 5 футов перемещения.\nТочный удар. Один раз за ход, когда вы совершаете по существу атаку оружием, вы можете совершить её с преимуществом. Если атака попадает, вы бросаете к8 и добавляете выпавшее число к броску урона от этой атаки. Вы можете использовать это преимущество количество раз, равное вашему бонусу мастерства, но использование расходуется только в том случае, если атака попадает. Вы восстанавливаете все потраченные использования, когда заканчиваете продолжительный отдых.\nЧленство в рыцарском ордене: рыцари Соламнии состоят только в одном ордене, но сохраняют все приобретённые черты рыцаря Соламнии даже при смене ордена.", "cards": [{"name": "Посадка в седло", "desc": "Посадка в седло и спешивание стоит вам всего 5 футов перемещения."}, {"name": "Точный удар", "desc": "Один раз за ход, когда вы совершаете по существу атаку оружием, вы можете совершить её с преимуществом. Если атака попадает, вы бросаете к8 и добавляете выпавшее число к броску урона от этой атаки. Вы можете использовать это преимущество количество раз, равное вашему бонусу мастерства, но использование расходуется только в том случае, если атака попадает. Вы восстанавливаете все потраченные использования, когда заканчиваете продолжительный отдых.", "rider": {"sides": 8, "count": 1, "note": "атака с преимуществом; кость добавляется при попадании", "consume": true}}]}, {"id": "initiate-of-high-sorcery", "name": "Посвящённый в Высшее волшебство", "nameEn": "Initiate of High Sorcery", "source": "Dragonlance: Shadow of the Dragon Queen", "prereq": "кампания в Саге о Копье; Чародей, Волшебник или предыстория «Маг Высшего Волшебства»", "desc": "Вы прошли обучение у заклинателей, связанных с Магами Высшего волшебства.\nВыберите одну из трёх лун Кринна, влияющих на вашу магию: чёрная луна Нуитари, красная луна Лунитари или белая луна Солинари. Вы изучаете один заговор на ваш выбор из списка заклинаний волшебника и два заклинания 1-го уровня согласно выбранной луне, как указано в таблице «Лунные заклинания»: Нуитари — выберите два из: диссонирующий шёпот, псевдожизнь, сглаз, луч болезни. Лунитари — два из: сверкающие брызги, маскировка, падение пёрышком, скороход. Солинари — два из: понимание языков, обнаружение зла и добра, защита от зла и добра, щит.\nВы можете накладывать каждое из выбранных заклинаний 1-го уровня без ячейки заклинания, и вы должны закончить продолжительный отдых, прежде чем вы сможете снова наложить их таким образом. Вы также можете наложить заклинания, используя любые имеющиеся у вас ячейки заклинаний.\nВашей базовой характеристикой для заклинаний этой черты — Интеллект, Мудрость или Харизма (определите при выборе этой черты).", "picks": [{"key": "spellAbility", "kind": "ability", "label": "Базовая характеристика заклинаний", "options": ["int", "wis", "cha"]}, {"key": "cantrip", "kind": "spell", "label": "Заговор волшебника", "level": 0, "count": 1, "cast": "cantrip", "lists": ["wizard"]}, {"key": "moon", "kind": "option", "label": "Луна Кринна", "options": [{"id": "nuitari", "label": "Нуитари (чёрная)"}, {"id": "lunitari", "label": "Лунитари (красная)"}, {"id": "solinari", "label": "Солинари (белая)"}]}, {"key": "spells", "kind": "spell", "label": "Два заклинания 1-го уровня выбранной луны", "level": 1, "count": 2, "cast": "free-long", "byKey": "moon", "map": {"nuitari": {"ids": ["dissonant-whispers", "false-life", "hex", "ray-of-sickness"]}, "lunitari": {"ids": ["color-spray", "disguise-self", "feather-fall", "longstrider"]}, "solinari": {"ids": ["comprehend-languages", "detect-evil-and-good", "protection-from-evil-and-good", "shield"]}}}]}, {"id": "knight-of-the-crown", "name": "Рыцарь Короны", "nameEn": "Knight of the Crown", "source": "Dragonlance: Shadow of the Dragon Queen", "prereq": "4 уровень, предыстория «Соламнийский Рыцарь»", "desc": "Вы рыцарь Соламнии, связанный с Орденом Короны, группой, которая превозносит добродетели сотрудничества, верности и послушания. Вы преуспеваете в групповом бою и получаете следующие преимущества:\nУвеличение характеристик. Увеличьте значение Силы, Ловкости или Телосложения на 1 при максимуме 20.\nКомандный клич. Бонусным действием вы можете приказать одному союзнику в пределах 30 футов от вас атаковать. Если этот союзник может видеть или слышать вас, он может реакцией немедленно совершить одну атаку оружием. Если атака попадает в цель, союзник может бросить к8 и добавить выпавшее число к броску урона от этой атаки. Вы можете использовать это бонусное действие количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда закончите продолжительный отдых.", "abilityIncrease": {"choices": ["str", "dex", "con"], "amount": 1}, "cards": [{"name": "Командный клич", "desc": "Бонусным действием вы можете приказать одному союзнику в пределах 30 футов от вас атаковать. Если этот союзник может видеть или слышать вас, он может реакцией немедленно совершить одну атаку оружием. Если атака попадает в цель, союзник может бросить к8 и добавить выпавшее число к броску урона от этой атаки. Вы можете использовать это бонусное действие количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда закончите продолжительный отдых."}]}, {"id": "knight-of-the-sword", "name": "Рыцарь Меча", "nameEn": "Knight of the Sword", "source": "Dragonlance: Shadow of the Dragon Queen", "prereq": "4 уровень, предыстория «Соламнийский Рыцарь»", "desc": "Вы рыцарь Соламнии, связанный с Орденом Меча, группой, посвященной героизму и мужеству. Храбрость укрепляет ваш дух, предоставляя следующие преимущества:\nУвеличение характеристик. Увеличьте значение Интеллекта, Мудрости или Харизмы на 1 при максимуме 20.\nДеморализующий удар. Один раз за ход, когда вы попадаете по существу броском атаки оружием, вы можете попытаться напугать эту цель. Цель должна совершить спасбросок Мудрости (Сл равен 8 + ваш бонус мастерства + модификатор характеристики, увеличенной этой чертой). При провале цель становится испуганной вами до конца вашего следующего хода. В случае успеха, цель, до конца своего следующего хода, совершает следующий бросок атаки с помехой. Вы можете использовать это преимущество количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все израсходованные использования, когда заканчиваете продолжительный отдых.", "abilityIncrease": {"choices": ["int", "wis", "cha"], "amount": 1}, "cards": [{"name": "Деморализующий удар", "desc": "Один раз за ход, когда вы попадаете по существу броском атаки оружием, вы можете попытаться напугать эту цель. Цель должна совершить спасбросок Мудрости (Сл равен 8 + ваш бонус мастерства + модификатор характеристики, увеличенной этой чертой). При провале цель становится испуганной вами до конца вашего следующего хода. В случае успеха, цель, до конца своего следующего хода, совершает следующий бросок атаки с помехой. Вы можете использовать это преимущество количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все израсходованные использования, когда заканчиваете продолжительный отдых."}]}, {"id": "knight-of-the-rose", "name": "Рыцарь Розы", "nameEn": "Knight of the Rose", "source": "Dragonlance: Shadow of the Dragon Queen", "prereq": "4 уровень, предыстория «Соламнийский Рыцарь»", "desc": "Вы рыцарь Соламнии, связанный с Орденом Розы, группой, известной своим лидерством, справедливостью и мудростью. Ваша решимость дает вам следующие преимущества:\nУвеличение характеристик. Увеличьте значение Телосложения, Мудрости или Харизмы на 1 при максимуме 20.\nПоддерживающий клич. Бонусным действием вы можете воззвать к одному существу, которое видите в пределах 30 футов от себя (вы можете выбрать себя). Если цель может вас видеть или слышать, она получает временные хиты, равные 1к8 + ваш бонус мастерства + модификатор характеристики, увеличенной этим умением. Вы можете использовать это бонусное действие количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда закончите продолжительный отдых.", "abilityIncrease": {"choices": ["con", "wis", "cha"], "amount": 1}, "cards": [{"name": "Поддерживающий клич", "desc": "Бонусным действием вы можете воззвать к одному существу, которое видите в пределах 30 футов от себя (вы можете выбрать себя). Если цель может вас видеть или слышать, она получает временные хиты, равные 1к8 + ваш бонус мастерства + модификатор характеристики, увеличенной этим умением. Вы можете использовать это бонусное действие количество раз, равное вашему бонусу мастерства, и вы восстанавливаете все потраченные использования, когда закончите продолжительный отдых."}]}, {"id": "strixhaven-initiate", "name": "Поступивший в Стриксхейвен", "nameEn": "Strixhaven initiate", "source": "Strixhaven: A Curriculum of Chaos", "prereq": "", "desc": "Вы ознакомились с некоторыми магическими теориями и выучили несколько заклинаний, связанных с Университетом Стриксхейвен.\nВыберите один из факультетов Стриксхейвена: Лорхолд, Призмари, Квандрикс, Сильверквилл или Визерблум. Вы узнаёте два заговора и одно заклинание 1-го уровня в зависимости от выбранного вами факультета, как указано в таблице «Заклинания Стриксхейвена».\nВы можете накладывать заклинание 1-го уровня без затрат ячеек заклинаний и вам необходимо закончить продолжительный отдых, чтобы наложить это заклинание подобным образом вновь. Вы также можете накладывать это заклинание, используя любые ячейки заклинаний, которые у вас есть.\nИнтеллект, Мудрость или Харизма является вашей базовой характеристикой для этого заклинания (выберите одну из них при получении этой черты).\nТаблица «Заклинания Стриксхейвена»: Лорхолд — заговоры (два из): свет, священное пламя, чудотворство; заклинание 1-го уровня из списка жреца или волшебника. Призмари — огненный снаряд, фокусы, луч холода; список барда или чародея. Квандрикс — искусство друидов, указание, волшебная рука; список друида или волшебника. Сильверквилл — священное пламя, чудотворство, злая насмешка; список барда или жреца. Визерблум — леденящее прикосновение, искусство друидов, уход за умирающим; список друида или волшебника.", "picks": [{"key": "spellAbility", "kind": "ability", "label": "Базовая характеристика заклинания", "options": ["int", "wis", "cha"]}, {"key": "faculty", "kind": "option", "label": "Факультет", "options": [{"id": "lorehold", "label": "Лорхолд"}, {"id": "prismari", "label": "Призмари"}, {"id": "quandrix", "label": "Квандрикс"}, {"id": "silverquill", "label": "Сильверквилл"}, {"id": "witherbloom", "label": "Визерблум"}]}, {"key": "cantrips", "kind": "spell", "label": "Два заговора факультета", "level": 0, "count": 2, "cast": "cantrip", "byKey": "faculty", "map": {"lorehold": {"ids": ["light", "sacred-flame", "thaumaturgy"]}, "prismari": {"ids": ["fire-bolt", "prestidigitation", "ray-of-frost"]}, "quandrix": {"ids": ["druidcraft", "guidance", "mage-hand"]}, "silverquill": {"ids": ["sacred-flame", "thaumaturgy", "vicious-mockery"]}, "witherbloom": {"ids": ["chill-touch", "druidcraft", "spare-the-dying"]}}}, {"key": "spell1", "kind": "spell", "label": "Заклинание 1-го уровня факультета", "level": 1, "count": 1, "cast": "free-long", "byKey": "faculty", "map": {"lorehold": {"lists": ["cleric", "wizard"]}, "prismari": {"lists": ["bard", "sorcerer"]}, "quandrix": {"lists": ["druid", "wizard"]}, "silverquill": {"lists": ["bard", "cleric"]}, "witherbloom": {"lists": ["druid", "wizard"]}}}]}, {"id": "strixhaven-mascot", "name": "Талисман Стриксхейвена", "nameEn": "Strixhaven Mascot", "source": "Strixhaven: A Curriculum of Chaos", "prereq": "4 уровень, черта «Поступивший в Стриксхейвен»", "desc": "Вы узнали, как призвать себе на помощь талисман Стриксхейвена, получая следующие преимущества:\n• Вы можете накладывать заклинание поиск фамильяра [find familiar] в качестве ритуала. Ваш фамильяр может принять форму талисмана, связанного с факультетом, который вы выбрали для черты Поступивший с Стриксхейвен: талисман–статуя духа [spirit statue mascot] (Лорхолд), талисман–элементаль искусства [art elemental mascot] (Призмари), талисман–фрактал [fractal mascot] (Квандрикс), талисман–чернильник [inkling mascot] (Сильверквилл) или талисман–вредитель [pest mascot] (Визерблум).\n• Кроме того, когда вы совершаете действие Атака, вы можете вместо одной своей атаки позволить атаковать один раз своему фамильяру талисману. При этом он совершает свою атаку реакцией.\n• Если ваш фамильяр талисман находится в пределах 60 футов от вас, то вы можете действием телепортироваться, поменявшись с фамильяром местами. Если место куда вы перемещаетесь слишком мало для вас, телепортация не удаётся и использование расходуется впустую. Как только вы телепортируетесь подобным образом, вы не можете сделать это снова, пока не закончите продолжительный отдых, если только вы не израсходуете ячейку заклинаний 2-го уровня или выше, чтобы сделать это снова.", "grant": {"spells": [{"id": "find-familiar", "use": "ritual"}]}, "cards": [{"name": "Талисман: атака фамильяра", "desc": "Когда вы совершаете действие Атака, вы можете вместо одной своей атаки позволить атаковать один раз вашему фамильяру-талисману; он совершает свою атаку реакцией."}, {"name": "Талисман: телепортация", "desc": "Если фамильяр-талисман находится в пределах 60 футов от вас, вы можете действием телепортироваться, поменявшись с ним местами. Если место слишком мало для вас, телепортация не удаётся и использование расходуется. Как только вы телепортируетесь подобным образом, вы не можете сделать это снова, пока не закончите продолжительный отдых, если только не израсходуете ячейку заклинаний 2-го уровня или выше."}]}];
  NEW_FEATS.forEach((f) => { if (!FEATS.some((x) => x.id === f.id)) FEATS.push(f); });
})();

// Раунд 61: черты, которые по правилам можно брать несколько раз («Одарённый посвящённый в магию» — каждый раз другой класс, «Умелец» — другие навыки).
(function markRepeatableFeats() {
  ["elemental-adept", "magic-initiate", "skilled"].forEach((id) => { const f = FEATS.find((x) => x.id === id); if (f) f.repeatable = true; });
})();

// ---- Round 62 additions --------------------------------------------------
// Заклинания подклассов следопыта и друида (domainSpells — всегда подготовлены/известны,
// в лимит не входят), полные тексты умений следопыта/друида, умения друида 1–20.
export const DRUID_LAND_TERRAINS = ["Арктика", "Побережье", "Пустыня", "Лес", "Луг", "Горы", "Болото", "Подземье"];
(function applyRound62Data() {
  const spellName = (id) => (SPELLS.find((s) => s.id === id) || {}).name || id;
  const mk = (levels, tiers) => levels.map((level, i) => ({ level, spells: tiers[i] }));
  const describe = (sub, title, unit, intro) => {
    const lines = [intro];
    sub.domainSpells.forEach((t) => lines.push(`${t.level}-й уровень ${unit}: ${t.spells.map(spellName).join(", ")}`));
    const f = sub.features.find((x) => x.name === title);
    if (f) f.desc = lines;
  };
  // --- Следопыт: заклинания подклассов (уровни следопыта 3/5/9/13/17)
  const ranger = CLASSES.find((c) => c.id === "ranger");
  if (ranger) {
    const R = [3, 5, 9, 13, 17];
    const SPELLS_BY_SLUG = {
      "horizon-walker": ["Магия странников горизонта", [["protection-from-evil-and-good"], ["misty-step"], ["haste"], ["banishment"], ["teleportation-circle"]]],
      "gloom-stalker": ["Магия сумрачного охотника", [["disguise-self"], ["rope-trick"], ["fear"], ["greater-invisibility"], ["seeming"]]],
      "monster-slayer": ["Магия убийцы чудовищ", [["protection-from-evil-and-good"], ["zone-of-truth"], ["magic-circle"], ["banishment"], ["hold-monster"]]],
      "fey-wanderer": ["Магия странника фей", [["charm-person"], ["misty-step"], ["dispel-magic"], ["dimension-door"], ["mislead"]]],
      "swarmkeeper": ["Магия хранителя роя", [["faerie-fire"], ["web"], ["gaseous-form"], ["arcane-eye"], ["insect-plague"]]],
    };
    ranger.subclasses.forEach((sub) => {
      const spec = SPELLS_BY_SLUG[sub.slug];
      if (!spec) return;
      sub.domainSpells = mk(R, spec[1]);
      describe(sub, spec[0], "следопыта", "Вы получаете дополнительные заклинания на указанных уровнях следопыта. Они считаются заклинаниями следопыта, всегда известны и не учитываются в числе известных вам заклинаний следопыта.");
    });
    // Полные тексты умений (раньше на карточке оставались только название и двоеточие)
    Object.assign(ranger.classFeatureText, {
      "Дополнительная атака": "Начиная с 5-го уровня, вы можете атаковать дважды вместо одного раза, когда в свой ход совершаете действие Атака.",
      "Первобытное чувство": "Начиная с 3-го уровня, вы можете действием потратить одну ячейку заклинаний следопыта, чтобы сосредоточить своё восприятие на окружающей местности. На 1 минуту за каждый круг потраченной ячейки вы чувствуете, есть ли в пределах 1 мили от вас (или до 6 миль, если вы в избранной местности) аберрации, небожители, драконы, элементали, феи, исчадия и нежить. Это умение не раскрывает местоположение и количество существ.",
      "Улучшенный избранный враг": "На 6-м и 14-м уровнях вы выбираете ещё один тип избранных врагов и язык, на котором они говорят, если он есть. Умение работает так же, как «Избранный враг».",
      "Более опытный следопыт": "На 6-м и 10-м уровнях вы выбираете ещё один тип избранной местности из списка «Исследователя природы». В избранной местности вы получаете все преимущества этого умения.",
      "Неутомимость следопыта": "Начиная с 8-го уровня, передвижение по немагической труднопроходимой местности не стоит вам дополнительного движения. Вы также можете проходить сквозь немагические растения, не замедляясь и не получая урона от них, даже если у них есть шипы или колючки. Кроме того, вы совершаете с преимуществом спасброски от растений, созданных или изменённых магией, чтобы замедлять передвижение.",
      "Пропасть без следа": "Начиная с 14-го уровня, вы можете бонусным действием совершить действие Засада (Скрытность). Кроме того, вас нельзя выследить немагическим способом, если вы сами не хотите оставлять следов.",
      "Звериные чувства": "На 18-м уровне вы получаете сверхъестественные чувства, помогающие бороться с существами, которых вы не видите. Когда вы атакуете существо, которое не видите, это не накладывает помеху на ваши броски атаки. Вы также знаете расположение любого невидимого существа в пределах 30 футов, если оно не спрятано от вас и вы не ослеплены и не оглушены.",
      "Победитель чудовищ": "На 20-м уровне вы становитесь непревзойдённым охотником на своих врагов. Один раз в свой ход вы можете добавить модификатор Мудрости к броску атаки или к броску урона атаки против одного из ваших избранных врагов. Вы можете решить использовать это умение до или после броска, но до применения его эффектов.",
    });
  }
  // --- Паладин: Дополнительная атака (тот же пробел в тексте)
  const palC = CLASSES.find((c) => c.id === "paladin");
  if (palC) palC.classFeatureText["Дополнительная атака"] = "Начиная с 5-го уровня, вы можете атаковать дважды вместо одного раза, когда в свой ход совершаете действие Атака.";
  const bard = CLASSES.find((c) => c.id === "bard");
  if (bard) {
    bard.classFeatureText = bard.classFeatureText || {};
    delete bard.classFeatureText["Знаток"];
    bard.classFeatureText["Мастер на все руки"] = "Начиная со 2-го уровня, вы можете добавлять половину вашего бонуса мастерства (с округлением вниз) к любой проверке характеристики, в которой вы не используете бонус мастерства.";
    bard.classFeatureText["Песнь отдыха"] = "Начиная со 2-го уровня, вы можете использовать успокаивающую музыку или речь, чтобы помочь раненым союзникам восстановить силы во время короткого отдыха. Если вы или любые дружественные существа, слышащие вашу игру, восстанавливают хиты в конце короткого отдыха, потратив Кости Хитов, каждое из этих существ восстанавливает дополнительно 1к6 хитов.\n\nДополнительные хиты возрастают при достижении определённого уровня в этом классе: до 1к8 на 9-м уровне, до 1к10 на 13-м уровне и до 1к12 на 17-м уровне.";
    bard.classFeatureText["Контрочарование"] = "Начиная с 6-го уровня, вы получаете возможность использовать музыку или слова силы, чтобы защититься от эффектов, влияющих на разум. Вы можете действием начать выступление, длящееся до конца вашего следующего хода. Во время этого выступления вы и все дружественные существа в пределах 30 футов от вас, которые вас слышат, получаете преимущество на спасброски от состояний «испуганный» и «очарованный».\n\nВыступление заканчивается досрочно, если вы становитесь недееспособным или теряете способность говорить.";
    bard.classFeatureText["Компетентность"] = "На 3-м уровне выберите два навыка, которыми вы владеете. Ваш бонус мастерства удваивается для всех проверок, использующих эти навыки. На 10-м уровне вы можете выбрать ещё два навыка, которыми владеете, и получить то же преимущество.";
  }
  // --- Друид
  const druid = CLASSES.find((c) => c.id === "druid");
  if (!druid) return;
  const SLOT_NOTE = (n) => `Заклинания ${n}-го круга`;
  druid.features = {
    1: ["Друидический", "Заклинания друида"],
    2: ["Дикий облик (2/короткий отдых)", "Круг друидов"],
    3: [SLOT_NOTE(2)],
    4: ["Черта или увеличение характеристик"],
    5: [SLOT_NOTE(3)],
    6: ["Умение архетипа"],
    7: [SLOT_NOTE(4)],
    8: ["Черта или увеличение характеристик"],
    9: [SLOT_NOTE(5)],
    10: ["Умение архетипа"],
    11: [SLOT_NOTE(6)],
    12: ["Черта или увеличение характеристик"],
    13: [SLOT_NOTE(7)],
    14: ["Умение архетипа"],
    15: [SLOT_NOTE(8)],
    16: ["Черта или увеличение характеристик"],
    17: [SLOT_NOTE(9)],
    18: ["Вечная юность", "Звериные заклинания"],
    19: ["Черта или увеличение характеристик"],
    20: ["Верховный друид"],
  };
  druid.classFeatureText = Object.assign(druid.classFeatureText || {}, {
    "Дикий облик": "Начиная со 2-го уровня, вы можете магическим образом принимать облик зверя, которого уже видели. Вы можете использовать это умение два раза. Вы восстанавливаете все потраченные использования после короткого или продолжительного отдыха.\n\nВы можете оставаться в облике зверя количество часов, равное половине вашего уровня друида (с округлением вниз). Затем вы возвращаетесь в обычный облик, если не потратите ещё одно использование. Раньше времени можно вернуться в обычный облик бонусным действием. Облик закончится сам, если вы будете без сознания, достигнете 0 хитов или умрёте.\n\nОграничения облика растут с уровнем: со 2-го уровня — показатель опасности до 1/4, без скорости полёта и плавания; с 4-го — до 1/2, без скорости полёта; с 8-го — до 1, включая полёт. Ваша статистика заменяется статистикой зверя, но вы сохраняете мировоззрение, личность, значения Интеллекта, Мудрости и Харизмы, а также владения навыками и спасбросками (зверь может добавить собственные). Вы не можете накладывать заклинания в обличье зверя, но это не мешает вам концентрироваться на уже наложенных заклинаниях.",
    "Друидический": "Вы знаете друидический — тайный язык друидов. Вы можете говорить на нём и использовать его, чтобы оставлять скрытые сообщения. Вы и все, кто знает этот язык, автоматически замечаете такие сообщения. Остальные замечают присутствие сообщения только при успешной проверке Мудрости (Восприятие) со Сл 15, но не могут прочесть его без магии.",
    "Вечная юность": "Начиная с 18-го уровня, магия природы замедляет ваше старение: каждые 10 лет вы стареете лишь на 1 год.",
    "Звериные заклинания": "Начиная с 18-го уровня, вы можете накладывать многие свои заклинания друида в любом облике «Дикого облика». Вы можете использовать соматические и вербальные компоненты заклинаний друида, находясь в облике зверя, но не можете предоставить материальные компоненты.",
    "Верховный друид": "На 20-м уровне вы можете использовать «Дикий облик» неограниченное количество раз. Кроме того, вы можете игнорировать вербальные и соматические компоненты своих заклинаний друида, а также материальные компоненты, у которых нет указанной стоимости и которые не расходуются заклинанием. Вы получаете это преимущество как в обычном, так и в облике «Дикого облика».",
  });
  druid.scalingNotes = {
    4: "«Дикий облик»: теперь доступны звери с показателем опасности до 1/2 (без скорости полёта); заговоры друида: ещё один.",
    8: "«Дикий облик»: теперь доступны звери с показателем опасности до 1, в том числе летающие.",
    10: "Заговоры друида: ещё один.",
    20: "«Дикий облик» без ограничения числа использований.",
  };
  // --- Друид: заклинания кругов (уровни друида)
  const circle = (slug) => druid.subclasses.find((s) => s.slug === slug);
  const wild = circle("wildfire");
  if (wild) {
    wild.domainSpells = mk([2, 3, 5, 7, 9], [["burning-hands", "cure-wounds"], ["flaming-sphere", "scorching-ray"], ["plant-growth", "revivify"], ["aura-of-life", "fire-shield"], ["flame-strike", "mass-cure-wounds"]]);
    describe(wild, "Заклинания круга", "друида", "Вы получаете заклинания круга дикого огня на указанных уровнях друида. Они всегда подготовлены и не учитываются в лимите подготовленных заклинаний. Если заклинания нет в списке друида, оно становится для вас заклинанием друида.");
  }
  const spores = circle("spores");
  if (spores) {
    spores.domainSpells = mk([3, 5, 7, 9], [["blindnessdeafness", "gentle-repose"], ["animate-dead", "gaseous-form"], ["blight", "confusion"], ["cloudkill", "contagion"]]);
    describe(spores, "Заклинания круга", "друида", "На 2-м уровне вы изучаете заговор леденящее прикосновение [chill touch]. Заклинания круга спор всегда подготовлены и не учитываются в лимите подготовленных заклинаний.");
  }
  const stars = circle("stars");
  if (stars) stars.domainSpells = [{ level: 2, spells: ["guiding-bolt"] }];
  const land = circle("land");
  if (land) {
    const T = (a) => mk([3, 5, 7, 9], a);
    land.terrainSpells = {
      "Арктика": T([["hold-person", "spike-growth"], ["sleet-storm", "slow"], ["freedom-of-movement", "ice-storm"], ["commune-with-nature", "cone-of-cold"]]),
      "Побережье": T([["mirror-image", "misty-step"], ["water-breathing", "water-walk"], ["control-water", "freedom-of-movement"], ["conjure-elemental", "scrying"]]),
      "Пустыня": T([["blur", "silence"], ["create-food-and-water", "protection-from-energy"], ["blight", "hallucinatory-terrain"], ["insect-plague", "wall-of-stone"]]),
      "Лес": T([["barkskin", "spider-climb"], ["call-lightning", "plant-growth"], ["divination", "freedom-of-movement"], ["commune-with-nature", "tree-stride"]]),
      "Луг": T([["invisibility", "pass-without-trace"], ["daylight", "haste"], ["divination", "freedom-of-movement"], ["dream", "insect-plague"]]),
      "Горы": T([["spider-climb", "spike-growth"], ["lightning-bolt", "meld-into-stone"], ["stone-shape", "stoneskin"], ["passwall", "wall-of-stone"]]),
      "Болото": T([["darkness", "melfs-acid-arrow"], ["water-walk", "stinking-cloud"], ["freedom-of-movement", "locate-creature"], ["insect-plague", "scrying"]]),
      "Подземье": T([["spider-climb", "web"], ["gaseous-form", "stinking-cloud"], ["greater-invisibility", "stone-shape"], ["cloudkill", "insect-plague"]]),
    };
  }
})();
// «Дополнительный заговор»/«Улучшенная малая иллюзия»: заговор, выдаваемый умением подкласса.
// fixed — конкретный заговор (если он уже известен — выбирается любой другой из списка list);
